                   ))}
                </div>
              </div>

              <div className="space-y-3">
                <label className="text-[10px] font-black text-slate-500 uppercase px-1">Vozidla (kliknutím vyber)</label>
                <div className="flex flex-wrap gap-2">
                   {vehicles.map(v => (
                     <button key={v.id} onClick={() => toggleResource(v.id, 'vehicle')} className={`px-4 py-2 rounded-xl text-[10px] font-black transition-all border ${currentTask.assignedVehicles?.includes(v.id) ? 'bg-red-600 border-red-500 text-white shadow-lg' : 'bg-slate-800 border-slate-700 text-slate-500'}`}>{v.plate}</button>
                   ))}
