                    <button 
                        onClick={parseNotesAndFill}
                        className="text-[9px] font-black text-blue-400 uppercase tracking-widest bg-blue-900/20 px-3 py-1 rounded-full hover:bg-blue-900/40 transition-colors flex items-center gap-1"
                    >
                        <Icons.Sparkles /> Rozpoznat údaje
                    </button>
                </div>
                <textarea 
                    value={currentTask.notes || ''} 
                    onChange={e => setCurrentTask({...currentTask, notes: e.target.value})} 
                    placeholder="Vložte text, např.: 'Karel Novák, 777123456, Nakládka: Praha 1, Vykládka: Brno'"
                    className="w-full bg-slate-800 rounded-xl p-4 text-sm text-white border-none min-h-[120px]"
                    rows={5}
                />
                <p className="text-[9px] text-slate-600 px-1">
                    Tip: Zkopírujte sem text emailu a klikněte na "Rozpoznat údaje" pro automatické vyplnění polí.
                </p>
              </div>

              <div className="flex gap-4 pt-4">
                <button onClick={() => setShowModal(false)} className="flex-1 text-slate-500 font-black uppercase text-xs tracking-widest">Zrušit</button>
                <button onClick={saveTask} className="flex-[2] bg-blue-600 text-white font-black py-4 rounded-2xl shadow-xl shadow-blue-600/20 uppercase text-xs tracking-widest">Uložit změny</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

