    { id: '1', name: 'Jan Novák', email: 'admin@stehovak2.com', phone: '777123456', role: 'Driver', status: 'Available' },
    { id: '2', name: 'Petr Svoboda', email: 'petr.svoboda@example.com', phone: '777654321', role: 'Loader', status: 'On Task' },
    { id: '3', name: 'Marek Kučera', email: 'marek.kucera@example.com', phone: '777987654', role: 'Loader', status: 'Available' },
  ]);
  const [vehicles, setVehicles] = useState<Vehicle[]>([
    { id: '1', plate: '1AB 1234', model: 'Iveco Daily', capacity: '15m3', status: 'Ready' },
    { id: '2', plate: '2BC 5678', model: 'Mercedes Sprinter', capacity: '12m3', status: 'In Use' },
  ]);

  const [transactions, setTransactions] = useState<Transaction[]>([
    { id: 'tr1', type: 'income', amount: 4500, description: 'Zakázka #t1 - Karel D.', date: new Date(), userId: '1', userName: 'Jan Novák' },
    { id: 'tr2', type: 'expense', amount: 2100, description: 'PHM - Shell Praha 4', date: new Date(), userId: '1', userName: 'Jan Novák' },
  ]);

  const getTomorrow = () => {
    const d = new Date();
    d.setDate(d.getDate() + 1);
    d.setHours(9, 0, 0, 0);
    return d;
  };

  const [tasks, setTasks] = useState<MoveTask[]>([
    {
      id: 't1',
      title: 'Stěhování bytu 2+kk',
      customer: 'Karel Dvořák',
      customerPhone: '+420 720 123 456',
      start: new Date(new Date().setHours(10, 0, 0, 0)),
      end: new Date(new Date().setHours(14, 0, 0, 0)),
      from: 'Praha 1',
      to: 'Praha 4',
      assignedWorkers: ['1', '2'],
      assignedVehicles: ['1'],
      status: 'Confirmed'
    },
    {
      id: 't2',
      title: 'Kanceláře "TechHub"',
      customer: 'Alena Modrá',
      customerPhone: '+420 603 444 555',
      start: getTomorrow(),
      end: new Date(getTomorrow().getTime() + 6 * 60 * 60 * 1000),
      from: 'Brno Střed',
      to: 'Ostrava - Poruba',
      assignedWorkers: ['3'],
      assignedVehicles: ['2'],
      status: 'Pending'
    }
  ]);

  useEffect(() => {
    // API Key Check for premium models
    const checkKey = async () => {
      // @ts-ignore
      if (window.aistudio) {
        // @ts-ignore
        const hasKey = await window.aistudio.hasSelectedApiKey();
        setApiKeySelected(hasKey);
      } else {
        // If aistudio is not available, assume we can proceed for local dev or other environments.
        setApiKeySelected(true); 
      }
      setCheckingApiKey(false);
    };
    // Use a timeout to ensure aistudio is loaded
    setTimeout(checkKey, 500);
  }, []);

  const handleSelectApiKey = async () => {
      // @ts-ignore
      if (window.aistudio) {
          // @ts-ignore
          await window.aistudio.openSelectKey();
          // Optimistically set to true to avoid race condition and proceed
          setApiKeySelected(true);
          setCheckingApiKey(false);
      }
  };

  const isClientIdValid = GOOGLE_CLIENT_ID && !GOOGLE_CLIENT_ID.startsWith('YOUR_') && !GOOGLE_CLIENT_ID.startsWith('VASE_') && GOOGLE_CLIENT_ID.endsWith('.apps.googleusercontent.com');

  const handleCredentialResponse = useCallback((response: any) => {
    if (response.error) {
       console.error("Google Auth Error:", response.error);
       setAuthError("Přihlášení selhalo. Zkontrolujte nastavení.");
       return;
    }

    const payload = decodeJwt(response.credential);
    if (payload) {
      const email = payload.email;
      const matchingWorker = workers.find(w => w.email?.toLowerCase() === email.toLowerCase());

      setUser({
        id: matchingWorker ? matchingWorker.id : 'user-' + Math.random().toString(36).substr(2, 4),
        name: payload.name || matchingWorker?.name || 'Uživatel Stěhovák',
        email: email,
        avatar: payload.picture || 'https://picsum.photos/seed/user/200/200',
        role: (matchingWorker?.id === '1' || email === 'admin@stehovak2.com') ? 'admin' : 'user',
        workerId: matchingWorker?.id
      });
      setAuthError(null);
    } else {
      setAuthError("Chyba při dekódování tokenu. Zkuste to znovu.");
    }
  }, [workers]);

  useEffect(() => {
    // If logged in or API key not selected yet, do nothing
    if (user || !apiKeySelected) return;

    let intervalId: any;

    const initializeGsi = () => {
      // @ts-ignore
      if (window.google && window.google.accounts && isClientIdValid) {
        // Stop checking once found
        clearInterval(intervalId);
        setIsGsiLoaded(true);

        try {
            // @ts-ignore
            window.google.accounts.id.initialize({
              client_id: GOOGLE_CLIENT_ID,
              callback: handleCredentialResponse,
              auto_select: false,
              ux_mode: 'popup', 
              cancel_on_tap_outside: true,
            });

            const btnElement = document.getElementById("googleBtn");
            if (btnElement) {
              // @ts-ignore
              window.google.accounts.id.renderButton(
                btnElement,
                { 
                  theme: "filled_blue", 
                  size: "large", 
                  width: 280, 
                  shape: "pill", 
                  text: "signin_with", 
                  locale: "cs",
                  logo_alignment: "left"
                }
              );
            }
        } catch (err) {
            console.error("GSI Init Error", err);
        }
      }
    };

    // Attempt immediately
    initializeGsi();

    // Check continuously until loaded
    intervalId = setInterval(initializeGsi, 500);

    return () => {
        clearInterval(intervalId);
        // @ts-ignore
        if (window.google?.accounts?.id) {
             // @ts-ignore
             window.google.accounts.id.cancel();
        }
    };
