      <div className="min-h-screen bg-[#0f172a] flex flex-col items-center justify-center p-6 text-white animate-fade-in relative overflow-hidden">
        <div className="absolute top-1/4 left-1/4 w-96 h-96 bg-blue-600/10 rounded-full blur-[120px] pointer-events-none" />
        <div className="absolute bottom-1/4 right-1/4 w-96 h-96 bg-red-600/10 rounded-full blur-[120px] pointer-events-none" />

        {/* LOGO SECTION - MASCOT STYLE */}
        <div className="w-64 h-64 mb-6 relative z-10 animate-fade-in hover:scale-105 transition-transform duration-500">
          <div className="w-full h-full flex items-center justify-center">
             <img 
               src={LOGO_URL} 
               alt="Stěhovák 2.0 Mascot" 
               className="w-full h-full object-contain filter drop-shadow-[0_20px_40px_rgba(0,0,0,0.5)]"
               onError={(e) => {
                 e.currentTarget.onerror = null; 
                 e.currentTarget.style.display = 'none';
                 e.currentTarget.parentElement!.innerHTML = '<div class="text-center bg-slate-800 rounded-3xl p-8 border border-slate-700"><p class="text-[60px]">🚛</p><p class="text-[10px] text-slate-400 font-bold mt-2">LOGO.PNG<br/>MISSING</p></div>';
               }}
             />
          </div>
        </div>

        <h1 className="text-4xl font-black mb-2 tracking-tighter relative z-10 text-center">Stěhovák <span className="text-red-500">2.0</span></h1>
        <p className="text-slate-400 mb-8 text-center font-medium max-w-[250px] relative z-10">
          Logistický systém pro moderní týmy.
        </p>

        <div className="space-y-4 w-full max-w-[320px] relative z-10 flex flex-col items-center">

          {/* Main Auth Buttons */}
          <div className="space-y-3 w-full">
            {isClientIdValid && (
               <div id="googleBtn" className="min-h-[44px] w-full flex justify-center"></div>
            )}

            <button 
                onClick={handleManualLogin}
                className="w-full bg-slate-800 text-white font-black py-3 rounded-full border border-slate-700 hover:bg-slate-700 transition-all text-xs uppercase tracking-widest shadow-lg active:scale-95"
            >
                Vstoupit v Demo Režimu
            </button>
          </div>

          {/* Dynamic URL Warning - Educational Block */}
          {isDynamicUrl && (
            <div className="w-full bg-yellow-500/10 p-4 rounded-2xl border border-yellow-500/20 text-center mt-4">
                 <p className="text-[9px] text-yellow-500 font-black uppercase tracking-widest mb-2 flex items-center justify-center gap-2">
                    <span className="text-sm">⚠️</span> Vývojové prostředí
                 </p>
                 <p className="text-[10px] text-slate-400 leading-relaxed mb-2">
                   Běžíte na dynamické adrese. Google přihlášení nemusí fungovat (Chyba 400), protože se adresa mění.
                 </p>
                 <div className="bg-black/20 rounded p-2 text-[9px] text-slate-500 font-mono mb-2 break-all">
                    {window.location.origin}
                 </div>
                 <p className="text-[9px] text-slate-300 font-bold">
                   Pro trvalé fungování: <br/> Publikujte aplikaci na pevnou doménu (Vercel, Netlify, Firebase).
                 </p>
            </div>
          )}
        </div>

        {authError && (
          <div className="mt-8 px-4 py-3 bg-red-500/10 border border-red-500/20 rounded-2xl animate-slide-up relative z-10">
            <p className="text-red-500 text-[10px] font-black uppercase tracking-widest text-center">
              {authError}
            </p>
          </div>
        )}

        <div className="absolute bottom-12 text-center w-full">
           <p className="text-[10px] text-slate-700 font-black uppercase tracking-[0.4em]">Premium Logistics Core</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#0f172a] flex flex-col w-full md:max-w-6xl mx-auto shadow-2xl overflow-hidden relative border-x border-slate-800">
      <header className="bg-slate-900/90 backdrop-blur-xl border-b border-slate-800 p-5 sticky top-0 z-40 flex items-center justify-between h-[80px]">
        <div className="flex items-center gap-3">
          <div className="w-14 h-14 flex items-center justify-center transition-transform hover:scale-110">
            <img src={LOGO_URL} alt="Stěhovák 2.0 Logo" className="w-full h-full object-contain filter drop-shadow-lg" />
          </div>
          <div>
            <h1 className="text-lg font-black text-white leading-none">Stěhovák <span className="text-red-500">2.0</span></h1>
            <p className="text-[9px] text-red-500 font-black tracking-widest mt-0.5">{getTabLabel(activeTab)}</p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <div className="w-10 h-10 rounded-2xl overflow-hidden border-2 border-slate-700 shadow-md">
            <img src={user.avatar} alt="Avatar" className="w-full h-full object-cover" />
          </div>
        </div>
        <div className="absolute bottom-0 left-0 w-full h-[2px] flex">
          <div className="h-full w-1/3 bg-blue-600"></div>
          <div className="h-full w-1/3 bg-slate-200"></div>
          <div className="h-full w-1/3 bg-red-600"></div>
        </div>
      </header>

      {authError && (
        <div className="p-4 bg-red-600/10 border-b border-red-500/20 text-center text-red-400 text-xs font-bold relative">
          <p className="pr-8">{authError}</p>
          <button onClick={() => setAuthError(null)} className="absolute top-1/2 right-4 -translate-y-1/2 text-red-400/50 hover:text-red-400 font-black text-xl">&times;</button>
        </div>
      )}

      <main className="flex-1 overflow-y-auto no-scrollbar p-5 pb-32">
        {activeTab === AppTab.DASHBOARD && <Dashboard tasks={tasks} workers={workers} vehicles={vehicles} user={user} />}
        {activeTab === AppTab.CALENDAR && <CalendarView tasks={tasks} setTasks={setTasks} workers={workers} vehicles={vehicles} user={user} />}
        {activeTab === AppTab.FLEET && <FleetView workers={workers} setWorkers={setWorkers} vehicles={vehicles} setVehicles={setVehicles} />}
        {activeTab === AppTab.AI_LAB && <AILab />}
        {activeTab === AppTab.PROFILE && (
          <Profile 
            user={user} 
            onLogout={() => setUser(null)} 
            transactions={transactions} 
            setTransactions={setTransactions} 
            tasks={tasks}
            workers={workers}
            vehicles={vehicles}
          />
        )}
      </main>

      <nav className="bg-slate-900/95 backdrop-blur-2xl border-t border-slate-800 fixed bottom-0 left-0 right-0 w-full md:max-w-6xl mx-auto z-40 flex justify-around p-4 shadow-[0_-10px_40px_rgba(0,0,0,0.5)] rounded-t-[35px]">
        <NavButton active={activeTab === AppTab.DASHBOARD} onClick={() => setActiveTab(AppTab.DASHBOARD)} icon={<Icons.Home />} label="Domů" />
        <NavButton active={activeTab === AppTab.CALENDAR} onClick={() => setActiveTab(AppTab.CALENDAR)} icon={<Icons.Calendar />} label="Kalendář" />
        <NavButton active={activeTab === AppTab.FLEET} onClick={() => setActiveTab(AppTab.FLEET)} icon={<Icons.Truck />} label="Flotila" />
        <NavButton active={activeTab === AppTab.AI_LAB} onClick={() => setActiveTab(AppTab.AI_LAB)} icon={<Icons.Sparkles />} label="AI Lab" />
        <NavButton active={activeTab === AppTab.PROFILE} onClick={() => setActiveTab(AppTab.PROFILE)} icon={<Icons.User />} label="Profil" />
      </nav>
    </div>
  );
};

interface NavButtonProps {
  active: boolean;
  onClick: () => void;
  icon: React.ReactNode;
  label: string;
}

const NavButton: React.FC<NavButtonProps> = ({ active, onClick, icon, label }) => (
  <button 
    onClick={onClick}
    className="flex flex-col items-center justify-center gap-1.5 transition-all relative"
  >
    <div className={`transition-all duration-300 ${active ? 'scale-110 -translate-y-1 text-blue-400' : 'scale-100 text-white'}`}>
      {icon}
    </div>
    <span className={`text-[9px] font-black uppercase tracking-wider transition-opacity duration-300 ${active ? 'opacity-100 text-blue-400' : 'opacity-60 text-slate-400'}`}>
      {label}
    </span>
    {active && <div className="absolute -bottom-1 w-1 h-1 bg-blue-600 rounded-full" />}
  </button>
);

export default App;

import React, { useState } from 'react';
import { Icons, COLORS } from '../constants';
import { Transaction, MoveTask, Worker, Vehicle } from '../types';

interface ProfileProps {
  user: { id: string, name: string, email: string, avatar: string, role: 'admin' | 'user', workerId?: string };
  onLogout: () => void;
  transactions: Transaction[];
  setTransactions: React.Dispatch<React.SetStateAction<Transaction[]>>;
  tasks: MoveTask[];
  workers: Worker[];
  vehicles: Vehicle[];
}

const Profile: React.FC<ProfileProps> = ({ user, onLogout, transactions, setTransactions, tasks, workers, vehicles }) => {
  const [activeDetail, setActiveDetail] = useState<string | null>(null);
  const [showTransactionModal, setShowTransactionModal] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Partial<Transaction> | null>(null);

  const isAdmin = user.role === 'admin';

  const userTransactions = isAdmin 
    ? [...transactions].sort((a, b) => a.userName.localeCompare(b.userName))
    : transactions.filter(t => t.userId === user.id);

  const handleAddTransaction = () => {
    setEditingTransaction({
      type: 'income',
      amount: 0,
      description: '',
      date: new Date(),
      userId: user.id,
      userName: user.name
    });
    setShowTransactionModal(true);
  };

  const handleEditTransaction = (tr: Transaction) => {
    if (!isAdmin && tr.userId !== user.id) return;
    setEditingTransaction({ ...tr });
    setShowTransactionModal(true);
  };

  const saveTransaction = () => {
    if (!editingTransaction || !editingTransaction.description || !editingTransaction.amount) return;

    const newTr = {
      ...editingTransaction,
      id: editingTransaction.id || Math.random().toString(36).substr(2, 9),
      date: editingTransaction.date || new Date(),
      userId: editingTransaction.userId || user.id,
      userName: editingTransaction.userName || user.name
    } as Transaction;

    if (editingTransaction.id) {
      setTransactions(transactions.map(t => t.id === newTr.id ? newTr : t));
    } else {
      setTransactions([newTr, ...transactions]);
    }
    setShowTransactionModal(false);
    setEditingTransaction(null);
  };

  // --- CSV Export Logic ---

  const formatValue = (value: any): string => {
    if (value === null || value === undefined) return '';
    if (value instanceof Date) return value.toLocaleString('cs-CZ');
    if (Array.isArray(value)) return value.join('; ');
    if (typeof value === 'object') return JSON.stringify(value).replace(/"/g, '""');
    return String(value).replace(/"/g, '""');
  };

  const generateCSV = (data: any[]) => {
    if (!data.length) return '';
    const headers = Object.keys(data[0]);
    const rows = data.map(obj => 
      headers.map(header => `"${formatValue(obj[header])}"`).join(',')
    );
    // Add BOM for Excel UTF-8 compatibility
    return '\uFEFF' + [headers.join(','), ...rows].join('\n');
  };

  const downloadCSV = (content: string, filename: string) => {
    const blob = new Blob([content], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', filename);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const exportTasks = () => {
    const data = tasks.map(t => ({
      ID: t.id,
      Název: t.title,
      Zákazník: t.customer,
      Telefon: t.customerPhone || '',
      Start: t.start,
      Konec: t.end,
      Odkud: t.from,
      Kam: t.to,
      Tým: t.assignedWorkers.map(id => workers.find(w => w.id === id)?.name || id).join(', '),
      Vozidla: t.assignedVehicles.map(id => vehicles.find(v => v.id === id)?.plate || id).join(', '),
      Stav: t.status,
      Poznámky: t.notes || ''
    }));
    downloadCSV(generateCSV(data), 'zakazky_export.csv');
  };

  const exportWorkers = () => {
    const data = workers.map(w => ({
      Jméno: w.name,
      Email: w.email || '',
      Telefon: w.phone,
      Pozice: w.role,
      Status: w.status
    }));
    downloadCSV(generateCSV(data), 'tym_export.csv');
  };

  const exportVehicles = () => {
    const data = vehicles.map(v => ({
      SPZ: v.plate,
      Model: v.model,
      Kapacita: v.capacity,
      Status: v.status,
      STK: v.stkExpiration || ''
    }));
    downloadCSV(generateCSV(data), 'flotila_export.csv');
  };

  const exportTransactions = () => {
    const data = transactions.map(t => ({
      Datum: t.date,
      Typ: t.type === 'income' ? 'Příjem' : 'Výdaj',
      Částka: t.amount,
      Popis: t.description,
      Autor: t.userName
    }));
    downloadCSV(generateCSV(data), 'transakce_export.csv');
  };

  // --- End CSV Export Logic ---

  const renderDetail = () => {
    switch (activeDetail) {
      case 'Informace o firmě':
        return (
          <div className="space-y-6">
            <div className="bg-slate-800 p-6 rounded-3xl border border-slate-700">
              <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">Název firmy</p>
              <p className="text-white font-bold">Stěhovák 2.0 Logistics s.r.o.</p>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="bg-slate-800 p-4 rounded-2xl border border-slate-700">
                <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">IČO</p>
                <p className="text-white font-bold text-sm">12345678</p>
              </div>
              <div className="bg-slate-800 p-4 rounded-2xl border border-slate-700">
                <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">DIČ</p>
                <p className="text-white font-bold text-sm">CZ12345678</p>
              </div>
            </div>
            <div className="bg-slate-800 p-6 rounded-3xl border border-slate-700">
              <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">Sídlo</p>
              <p className="text-white font-bold text-sm">Logistická 42, 110 00 Praha 1</p>
            </div>
          </div>
        );
      case 'Přijaté platby a výdaje':
        return (
          <div className="space-y-3">
            <button 
              onClick={handleAddTransaction}
              className="w-full bg-blue-600/20 text-blue-400 font-black py-3 rounded-2xl border border-blue-500/30 mb-2 uppercase text-[10px] tracking-widest flex items-center justify-center gap-2"
            >
              <Icons.Plus /> Přidat položku
            </button>
            <div className="max-h-[300px] overflow-y-auto no-scrollbar space-y-2">
              {userTransactions.length > 0 ? userTransactions.map(tr => (
                <div 
                  key={tr.id} 
                  onClick={() => handleEditTransaction(tr)}
                  className="bg-slate-800 p-4 rounded-2xl border border-slate-700 flex justify-between items-center group cursor-pointer hover:border-blue-500/50 transition-all"
                >
                  <div className="flex-1 min-w-0 mr-4">
                    <p className="text-white font-bold text-sm truncate">{tr.description}</p>
                    <div className="flex items-center gap-2">
                      <p className="text-[9px] text-slate-500 font-black uppercase">{tr.type === 'income' ? 'Příjem' : 'Výdaj'}</p>
                      {isAdmin && (
                        <span className="text-[9px] bg-slate-900 px-2 py-0.5 rounded text-blue-400 border border-slate-700 font-black truncate max-w-[80px]">
                          {tr.userName}
                        </span>
                      )}
                    </div>
                  </div>
                  <span className={`font-black whitespace-nowrap ${tr.type === 'income' ? 'text-green-500' : 'text-red-500'}`}>
                    {tr.type === 'income' ? '+' : '-'} {tr.amount.toLocaleString()} Kč
                  </span>
                </div>
              )) : (
                <p className="text-slate-600 text-center py-4 text-xs font-bold uppercase">Žádné záznamy</p>
              )}
            </div>
          </div>
        );
      case 'Notifikační Hub':
        return (
          <div className="space-y-4">
            <ToggleItem label="Push notifikace" checked={true} />
            <ToggleItem label="Emailové reporty" checked={false} />
            <ToggleItem label="SMS upozornění" checked={true} />
          </div>
        );
      case 'Export Dat':
        return (
          <div className="space-y-4">
             <div className="bg-slate-800/50 p-4 rounded-2xl border border-slate-700/50 mb-4">
               <p className="text-slate-400 text-xs font-bold text-center leading-relaxed">
                 Data budou stažena ve formátu CSV. Tento formát je kompatibilní s Excelem a Google Sheets.
               </p>
             </div>
             <ExportButton label="Exportovat Zakázky" onClick={exportTasks} icon={<Icons.Calendar />} />
             <ExportButton label="Exportovat Tým" onClick={exportWorkers} icon={<Icons.User />} />
             <ExportButton label="Exportovat Flotilu" onClick={exportVehicles} icon={<Icons.Truck />} />
             <ExportButton label="Exportovat Transakce" onClick={exportTransactions} icon={<Icons.Sparkles />} />
          </div>
        );
      case 'O Aplikaci':
        return (
          <div className="space-y-6">
            <div className="bg-slate-800 p-6 rounded-3xl border border-slate-700 text-center">
              <div className="w-24 h-24 mx-auto mb-4 relative">
                 <img src="/logo.png" alt="App Logo" className="w-full h-full object-contain drop-shadow-2xl" />
              </div>
              <h4 className="text-xl font-black text-white tracking-tighter">Stěhovák 2.0</h4>
              <p className="text-[10px] text-slate-500 font-black uppercase tracking-[0.2em] mt-1">Logistics Core</p>
            </div>
            <div className="space-y-2">
              <div className="flex justify-between p-4 bg-slate-800 rounded-2xl border border-slate-700">
                <span className="text-xs font-bold text-slate-500 uppercase tracking-widest">Verze</span>
                <span className="text-xs font-black text-white">2.0.4 Premium</span>
              </div>
              <div className="flex justify-between p-4 bg-slate-800 rounded-2xl border border-slate-700">
                <span className="text-xs font-bold text-slate-500 uppercase tracking-widest">Vývoj</span>
                <span className="text-xs font-black text-blue-400">Vítězslav Gerčák</span>
              </div>
              <div className="flex justify-between p-4 bg-slate-800 rounded-2xl border border-slate-700">
                <span className="text-xs font-bold text-slate-500 uppercase tracking-widest">Licence</span>
                <span className="text-xs font-black text-green-500">Aktivní</span>
              </div>
            </div>
            <div className="space-y-4">
              <p className="text-[10px] text-slate-400 text-center font-bold px-4 leading-relaxed">
                Tento systém je navržen pro maximální efektivitu stěhovacích týmů a plánování zakázek s využitím pokročilých AI technologií.
              </p>
              <p className="text-[10px] text-slate-400 text-center font-bold px-4 leading-relaxed border-t border-slate-800 pt-4">
                Tato aplikace byla vytvořena výhradně pro interní použití společnosti Stěhování Matěj a nesmí s ní být nijak nakládáno, bez výslovného souhlasu jejího vlastníka a vývojáře ( Vítězslav Gerčák ).
              </p>
            </div>
          </div>
        );
      default:
        return <p className="text-slate-500 text-center italic">Sekce ve vývoji...</p>;
    }
  };

  return (
    <div className="space-y-8 flex flex-col items-center animate-fade-in">
      <div className="text-center mt-8">
        <div className="w-32 h-32 rounded-[40px] border-4 border-slate-800 shadow-2xl mx-auto overflow-hidden relative mb-6">
          <img src={user.avatar} alt="Profile" className="w-full h-full object-cover" />
        </div>
        <div className="flex flex-col items-center gap-1">
           <h2 className="text-2xl font-black text-white tracking-tighter uppercase">{user.name}</h2>
           {isAdmin && <span className="text-[8px] bg-red-600 text-white px-3 py-0.5 rounded-full font-black uppercase tracking-widest">Administrátor</span>}
        </div>
        <p className="text-slate-500 text-sm font-bold uppercase tracking-widest mt-1">{user.email}</p>

        {user.workerId && (
          <div className="mt-4 inline-flex items-center gap-2 bg-blue-900/30 px-4 py-1.5 rounded-full border border-blue-500/30">
            <div className="w-1.5 h-1.5 bg-blue-400 rounded-full animate-pulse shadow-[0_0_8px_#60a5fa]" />
            <span className="text-[9px] font-black text-blue-400 uppercase tracking-widest">Identita Ověřena</span>
          </div>
        )}
      </div>

      <div className="w-full space-y-3">
        <SettingItem 
          label="Informace o firmě" 
          icon="🏢" 
          onClick={() => setActiveDetail('Informace o firmě')} 
        />
        <SettingItem 
          label="Notifikační Hub" 
          icon="🔔" 
          onClick={() => setActiveDetail('Notifikační Hub')} 
        />
        <SettingItem 
          label="Přijaté platby a výdaje" 
          icon="💳" 
          onClick={() => setActiveDetail('Přijaté platby a výdaje')} 
        />
        <SettingItem 
          label="Export Dat" 
          icon="💾" 
          onClick={() => setActiveDetail('Export Dat')} 
        />
        <SettingItem 
          label="O Aplikaci" 
          icon="🚀" 
          onClick={() => setActiveDetail('O Aplikaci')} 
        />
      </div>

      <button 
        onClick={onLogout}
        className="w-full py-5 text-red-500 font-black bg-red-950/20 border border-red-900/30 rounded-[2rem] mt-8 hover:bg-red-950/40 transition-all active:scale-[0.98] uppercase tracking-[0.2em] text-xs"
      >
        Ukončit Relaci
      </button>

      <p className="text-[10px] text-slate-700 font-black uppercase tracking-[0.3em] text-center pt-4">Logistics Core v2.0.4</p>

      {/* Detail Modal */}
      {activeDetail && (
        <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-lg z-50 flex items-end sm:items-center justify-center p-4">
          <div className="bg-slate-900 w-full max-w-md rounded-[32px] p-8 border border-slate-800 animate-slide-up shadow-2xl overflow-y-auto no-scrollbar max-h-[90vh]">
            <div className="flex justify-between items-center mb-8">
              <h3 className="text-xl font-black text-white uppercase tracking-tighter">{activeDetail}</h3>
              <button onClick={() => setActiveDetail(null)} className="p-2 bg-slate-800 rounded-xl text-slate-400 hover:text-white transition-colors">
                <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
              </button>
            </div>

            {renderDetail()}

            <button 
              onClick={() => setActiveDetail(null)}
              className="w-full bg-slate-800 text-white font-black py-4 rounded-2xl mt-8 uppercase text-[10px] tracking-widest"
            >
              Zavřít detail
            </button>
          </div>
        </div>
