      )}

      {/* Main Task Lists Container - Responsive Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 md:gap-12">
        <section className="space-y-5 md:space-y-8">
            <div className="flex items-center justify-between px-2">
            <h2 className="text-xl md:text-3xl font-black text-slate-100 tracking-tighter uppercase">Dnešní <span className="text-red-500">Mise</span></h2>
            <div className="w-2 h-2 md:w-3 md:h-3 rounded-full bg-red-500 animate-pulse shadow-[0_0_8px_#ef4444]" />
