import React, { useState, useMemo } from 'react';
import { MoveTask, Worker, Vehicle } from '../types';
import { Icons, COLORS } from '../constants';
import { geminiService } from '../services/geminiService';

interface CalendarViewProps {
  tasks: MoveTask[];
  setTasks: React.Dispatch<React.SetStateAction<MoveTask[]>>;
  workers: Worker[];
  vehicles: Vehicle[];
  user: { role: 'admin' | 'user' };
}

type ViewMode = 'day' | 'week';

const CalendarView: React.FC<CalendarViewProps> = ({ tasks, setTasks, workers, vehicles, user }) => {
  const [viewMode, setViewMode] = useState<ViewMode>('day');
  const [currentDate, setCurrentDate] = useState(new Date());
  const [showModal, setShowModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  const [currentTask, setCurrentTask] = useState<Partial<MoveTask>>({
    title: '', customer: '', customerPhone: '', from: '', to: '',
    status: 'Pending', notes: '', assignedWorkers: [], assignedVehicles: []
  });

  const isSameDay = (d1: Date, d2: Date) => 
    d1.getFullYear() === d2.getFullYear() &&
    d1.getMonth() === d2.getMonth() &&
    d1.getDate() === d2.getDate();

  const getMonday = (d: Date) => {
    const date = new Date(d);
    const day = date.getDay();
    const diff = date.getDate() - day + (day === 0 ? -6 : 1); 
    return new Date(date.setDate(diff));
  };

  const navigateDate = (direction: 'prev' | 'next') => {
    const newDate = new Date(currentDate);
    if (viewMode === 'day') {
      newDate.setDate(currentDate.getDate() + (direction === 'next' ? 1 : -1));
    } else {
      newDate.setDate(currentDate.getDate() + (direction === 'next' ? 7 : -7));
    }
    setCurrentDate(newDate);
  };

  const START_HOUR = 6;
  const END_HOUR = 22;
  const HOUR_HEIGHT = 90;

  const handleOpenCreate = () => {
    setIsEditing(false);
    const start = new Date(currentDate);
    start.setHours(9, 0, 0, 0);
    const end = new Date(start.getTime() + 3 * 60 * 60 * 1000);
    setCurrentTask({
      title: '', customer: '', customerPhone: '', from: '', to: '',
      status: 'Pending', start, end, assignedWorkers: [], assignedVehicles: [], notes: ''
    });
    setShowModal(true);
  };

  const handleOpenEdit = (task: MoveTask) => {
    setIsEditing(true);
    setCurrentTask({ ...task });
    setShowModal(true);
  };

  const saveTask = () => {
    if (!currentTask.title || !currentTask.start || !currentTask.end) return;
    const taskData = {
      ...currentTask,
      id: currentTask.id || Math.random().toString(36).substr(2, 9),
      start: new Date(currentTask.start),
      end: new Date(currentTask.end)
    } as MoveTask;

    if (isEditing) {
      setTasks(tasks.map(t => t.id === taskData.id ? taskData : t));
    } else {
      setTasks([...tasks, taskData]);

      // --- AUTOMATICKÁ NOTIFIKACE (SMS - HROMADNÁ) ---
      // Pokud je to nová zakázka, pošli SMS všem přiřazeným pracovníkům
      const assignedTeam = workers.filter(w => w.id && taskData.assignedWorkers.includes(w.id));

      if (assignedTeam.length > 0) {
        // Získat všechna telefonní čísla oddělená čárkou (standard pro hromadné SMS)
        const recipients = assignedTeam
            .map(w => w.phone.replace(/\s+/g, '')) // Odstranit mezery
            .filter(p => p.length > 0)
            .join(',');

        const dateStr = taskData.start.toLocaleDateString('cs-CZ');
        const timeStr = taskData.start.toLocaleTimeString('cs-CZ', { hour: '2-digit', minute: '2-digit' });

        // Formátování pro SMS (bez Markdownu, stručné)
        const msg = `🚚 NOVÁ ZAKÁZKA: ${taskData.title}\n` +
                    `📅 ${dateStr} v ${timeStr}\n` +
                    `📍 Z: ${taskData.from}\n` +
                    `🏁 Do: ${taskData.to}\n` +
                    `👤 Klient: ${taskData.customer}\n` +
                    `📞 ${taskData.customerPhone}\n` +
                    `📝 ${taskData.notes || ''}`;

        setTimeout(() => {
            // Otevření nativní aplikace Zprávy s předvyplněnými čísly a textem
            // 'sms:' schéma s oddělovačem čárkou funguje na většině Androidů i iOS pro hromadné zprávy
            window.open(`sms:${recipients}?body=${encodeURIComponent(msg)}`, '_self');
        }, 300);
      }
      // ----------------------------------------
    }
    setShowModal(false);
  };

  const toggleResource = (id: string, type: 'worker' | 'vehicle') => {
    if (type === 'worker') {
      const current = currentTask.assignedWorkers || [];
      const updated = current.includes(id) ? current.filter(wid => wid !== id) : [...current, id];
      setCurrentTask({...currentTask, assignedWorkers: updated});
    } else {
      const current = currentTask.assignedVehicles || [];
      const updated = current.includes(id) ? current.filter(vid => vid !== id) : [...current, id];
      setCurrentTask({...currentTask, assignedVehicles: updated});
    }
  };

  const formatForInput = (date?: Date) => {
    if (!date) return '';
    const d = new Date(date);
    d.setMinutes(d.getMinutes() - d.getTimezoneOffset());
    return d.toISOString().slice(0, 16);
  };

  const openMap = (address?: string) => {
    if (!address) return;
    window.open(`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(address)}`, '_blank');
  };

  // Funkce pro chytré rozpoznání údajů z poznámky pomocí AI
  const parseNotesAndFill = async () => {
    if (!currentTask.notes || isAnalyzing) return;

    setIsAnalyzing(true);
    try {
      const extractedData = await geminiService.extractTaskFromNotes(currentTask.notes);

      const updates: Partial<MoveTask> = {};
      if (extractedData.title) updates.title = extractedData.title;
      if (extractedData.customer) updates.customer = extractedData.customer;
      if (extractedData.customerPhone) updates.customerPhone = extractedData.customerPhone;
      if (extractedData.from) updates.from = extractedData.from;
      if (extractedData.to) updates.to = extractedData.to;

      // Aplikace změn pouze pro nevyplněná pole nebo přepis
      setCurrentTask(prev => ({ ...prev, ...updates }));
    } catch (e) {
      console.error("Chyba při AI analýze:", e);
      alert("Nepodařilo se automaticky rozpoznat údaje. Zkontrolujte připojení nebo API klíč.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const renderDayView = () => {
    const dayTasks = tasks.filter(task => isSameDay(task.start, currentDate));
    return (
      <div className="flex-1 overflow-y-auto no-scrollbar relative p-5 md:p-8 pt-4 bg-slate-900">
        <div className="absolute left-4 top-4 bottom-0 w-12 z-10 pointer-events-none text-slate-700 text-[10px] md:text-xs font-black">
          {Array.from({ length: END_HOUR - START_HOUR + 1 }).map((_, i) => (
            <div key={i} style={{ height: `${HOUR_HEIGHT}px` }}>{START_HOUR + i}:00</div>
          ))}
        </div>
        <div className="ml-14 relative h-full min-h-[1440px]">
           {Array.from({ length: END_HOUR - START_HOUR + 1 }).map((_, i) => (
             <div key={i} className="border-t border-slate-800 absolute w-full pointer-events-none" style={{ top: `${i * HOUR_HEIGHT}px` }} />
           ))}
           {isSameDay(currentDate, new Date()) && (
              <div className="absolute left-0 right-0 border-t-2 border-red-500 z-10 flex items-center pointer-events-none" style={{ top: `${(new Date().getHours() - START_HOUR + new Date().getMinutes()/60) * HOUR_HEIGHT}px` }}>
                <div className="w-2 h-2 rounded-full bg-red-500 -ml-1 shadow-[0_0_10px_#ef4444]" />
              </div>
            )}
           {dayTasks.map(task => {
             const startHour = task.start.getHours() + task.start.getMinutes()/60;
             const endHour = task.end.getHours() + task.end.getMinutes()/60;
             const top = (startHour - START_HOUR) * HOUR_HEIGHT;
             const height = (endHour - startHour) * HOUR_HEIGHT;
             return (
               <div key={task.id} onClick={() => handleOpenEdit(task)} className="absolute w-full p-1 z-20" style={{ top: `${top}px`, height: `${height}px` }}>
                 <div className={`h-full w-full rounded-2xl border p-4 shadow-lg flex flex-col justify-between overflow-hidden ${task.status === 'Confirmed' ? 'bg-blue-600 border-blue-500 text-white' : 'bg-red-600 border-red-500 text-white'}`}>
                   <div>
                     <h4 className="text-xs md:text-lg font-black leading-none truncate">{task.title}</h4>
                     <p className="text-[9px] md:text-sm font-bold opacity-70 uppercase mt-1 truncate">{task.customer}</p>
                   </div>
                   <p className="text-[8px] md:text-xs font-black uppercase text-right opacity-60">{task.start.getHours()}:{task.start.getMinutes().toString().padStart(2, '0')}</p>
                 </div>
               </div>
             );
           })}
        </div>
      </div>
    );
  };

  const renderWeekView = () => {
    const monday = getMonday(currentDate);
    const weekDays = Array.from({ length: 7 }).map((_, i) => {
      const d = new Date(monday);
      d.setDate(monday.getDate() + i);
      return d;
    });

    return (
      <div className="flex-1 overflow-y-auto no-scrollbar p-5 md:p-8 space-y-4 bg-slate-900">
        {weekDays.map((day, idx) => {
          const dayTasks = tasks.filter(t => isSameDay(t.start, day));
          const isToday = isSameDay(day, new Date());
          return (
            <div key={idx} className={`bg-slate-800 rounded-3xl p-5 border-2 transition-all ${isToday ? 'border-red-600 shadow-[0_0_20px_rgba(220,38,38,0.1)]' : 'border-slate-700'}`}>
              <div className="flex justify-between items-center mb-4">
                <div>
                  <h4 className={`text-sm md:text-lg font-black uppercase tracking-widest ${isToday ? 'text-red-500' : 'text-slate-100'}`}>
                    {day.toLocaleDateString('cs-CZ', { weekday: 'long' })}
                  </h4>
                  <p className="text-[10px] md:text-sm font-bold text-slate-500 mt-0.5">{day.toLocaleDateString('cs-CZ', { day: 'numeric', month: 'long' })}</p>
                </div>
                {dayTasks.length > 0 && <span className="bg-slate-900 text-blue-400 text-[10px] md:text-xs font-black px-3 py-1 rounded-full border border-slate-700">{dayTasks.length} akce</span>}
              </div>

              <div className="space-y-2">
                {dayTasks.length > 0 ? dayTasks.map(task => (
                  <div key={task.id} onClick={() => handleOpenEdit(task)} className="bg-slate-900/50 p-3 md:p-4 rounded-xl border border-slate-700/50 flex items-center justify-between group cursor-pointer hover:bg-slate-900 transition-all">
                    <div className="flex items-center gap-3">
                      <div className={`w-1.5 h-1.5 md:w-2 md:h-2 rounded-full ${task.status === 'Confirmed' ? 'bg-blue-500' : 'bg-red-500'}`} />
                      <div>
                        <p className="text-xs md:text-base font-bold text-slate-200 group-hover:text-blue-400 transition-colors">{task.title}</p>
                        <p className="text-[9px] md:text-xs text-slate-500 font-black uppercase">{task.customer}</p>
                      </div>
                    </div>
                    <span className="text-[10px] md:text-sm font-black text-slate-600">{task.start.getHours()}:{task.start.getMinutes().toString().padStart(2, '0')}</span>
                  </div>
                )) : (
                  <p className="text-[10px] md:text-xs text-slate-600 italic font-medium px-1">Žádné zakázky na tento den.</p>
                )}
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  const getNavigationLabel = () => {
    if (viewMode === 'day') {
      return currentDate.toLocaleDateString('cs-CZ', { day: 'numeric', month: 'long' });
    } else {
      const monday = getMonday(currentDate);
      const sunday = new Date(monday);
      sunday.setDate(monday.getDate() + 6);
      return `${monday.getDate()}. - ${sunday.getDate()}. ${sunday.toLocaleDateString('cs-CZ', { month: 'long' })}`;
    }
  };

  return (
    <div className="space-y-6">
      {/* View Switcher */}
      <div className="flex items-center justify-between">
        <div className="flex bg-slate-900 p-1 rounded-2xl border border-slate-800 shadow-inner">
          <button 
            onClick={() => setViewMode('day')}
            className={`px-6 py-2 rounded-xl text-[10px] md:text-sm font-black uppercase tracking-widest transition-all ${viewMode === 'day' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-600 hover:text-slate-400'}`}
          >
            Den
          </button>
          <button 
            onClick={() => setViewMode('week')}
            className={`px-6 py-2 rounded-xl text-[10px] md:text-sm font-black uppercase tracking-widest transition-all ${viewMode === 'week' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-600 hover:text-slate-400'}`}
          >
            Týden
          </button>
        </div>
        {user.role === 'admin' && (
          <button onClick={handleOpenCreate} className="bg-red-600 text-white p-3 md:p-4 rounded-2xl shadow-xl shadow-red-600/30 active:scale-95 transition-all">
            <Icons.Plus />
          </button>
        )}
      </div>

      {/* Navigation */}
      <div className="bg-slate-800 rounded-[2rem] p-5 shadow-sm border border-slate-700 flex items-center justify-between">
        <button onClick={() => navigateDate('prev')} className="p-3 text-slate-500 hover:text-white transition-colors">
          <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round"><path d="m15 18-6-6 6-6"/></svg>
        </button>
        <div className="text-center">
          <p className="text-xs md:text-lg font-black text-slate-100 uppercase tracking-widest">
            {getNavigationLabel()}
          </p>
          {viewMode === 'day' && <p className="text-[10px] md:text-sm font-bold text-red-500 uppercase tracking-widest mt-0.5">{currentDate.toLocaleDateString('cs-CZ', { weekday: 'long' })}</p>}
          {viewMode === 'week' && <p className="text-[10px] md:text-sm font-bold text-blue-500 uppercase tracking-widest mt-0.5">Týdenní přehled</p>}
        </div>
        <button onClick={() => navigateDate('next')} className="p-3 text-slate-500 hover:text-white transition-colors">
          <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round"><path d="m9 18 6-6-6-6"/></svg>
        </button>
      </div>

      {/* Main Content Area */}
      <div className="bg-slate-800 rounded-[3rem] shadow-sm border border-slate-700 overflow-hidden flex flex-col h-[600px] md:h-[800px] relative">
        {viewMode === 'day' ? renderDayView() : renderWeekView()}
      </div>

      {/* Task Edit Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-slate-950/95 backdrop-blur-lg z-50 flex items-end sm:items-center justify-center p-4">
          <div className="bg-slate-900 w-full max-w-lg rounded-[32px] p-8 border border-slate-800 animate-slide-up max-h-[90vh] overflow-y-auto no-scrollbar shadow-2xl">
            <h3 className="text-2xl font-black text-white mb-6 uppercase tracking-tighter">{isEditing ? 'Upravit zakázku' : 'Nová zakázka'}</h3>
            <div className="space-y-6">
              <div className="space-y-1">
                <label className="text-xs font-black text-white uppercase px-1">Název akce</label>
                <input value={currentTask.title} onChange={e => setCurrentTask({...currentTask, title: e.target.value})} placeholder="např. Stěhování bytu 3+1" className="w-full bg-slate-800 rounded-xl p-4 text-white border-none font-bold" />
              </div>
              <div className="grid grid-cols-2 gap-4">
                 <div className="space-y-1">
                    <label className="text-xs font-black text-white uppercase px-1">Zákazník</label>
                    <input value={currentTask.customer} onChange={e => setCurrentTask({...currentTask, customer: e.target.value})} className="w-full bg-slate-800 rounded-xl p-3 text-sm text-white border-none" />
                 </div>
                 <div className="space-y-1">
                    <label className="text-xs font-black text-white uppercase px-1">Telefon</label>
                    <input value={currentTask.customerPhone} onChange={e => setCurrentTask({...currentTask, customerPhone: e.target.value})} className="w-full bg-slate-800 rounded-xl p-3 text-sm text-white border-none" />
                 </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                 <div className="space-y-1">
                    <label className="text-xs font-black text-white uppercase px-1">Začátek</label>
                    <input type="datetime-local" value={formatForInput(currentTask.start)} onChange={e => setCurrentTask({...currentTask, start: new Date(e.target.value)})} className="w-full bg-slate-800 rounded-xl p-3 text-xs text-white border-none" />
                 </div>
                 <div className="space-y-1">
                    <label className="text-xs font-black text-white uppercase px-1">Konec</label>
                    <input type="datetime-local" value={formatForInput(currentTask.end)} onChange={e => setCurrentTask({...currentTask, end: new Date(e.target.value)})} className="w-full bg-slate-800 rounded-xl p-3 text-xs text-white border-none" />
                 </div>
              </div>

              {/* Adresní pole bez sekce Logistika */}
              <div className="space-y-3">
                <div className="space-y-1">
                    <label className="text-xs font-black text-white uppercase px-1">Nakládka (Odkud)</label>
                    <div className="flex gap-2">
                        <input 
                            value={currentTask.from} 
                            onChange={e => setCurrentTask({...currentTask, from: e.target.value})} 
                            placeholder="Ulice, Město" 
                            className="flex-1 bg-slate-800 rounded-xl p-3 text-sm text-white border-none" 
                        />
                        <button 
                            onClick={() => openMap(currentTask.from)}
                            className="bg-slate-800 text-blue-400 p-3 rounded-xl hover:bg-slate-700 transition-colors border border-slate-700"
                            title="Otevřít v mapách"
                        >
                            <Icons.Map />
                        </button>
                    </div>
                </div>
                <div className="space-y-1">
                    <label className="text-xs font-black text-white uppercase px-1">Vykládka (Kam)</label>
                    <div className="flex gap-2">
                        <input 
                            value={currentTask.to} 
                            onChange={e => setCurrentTask({...currentTask, to: e.target.value})} 
                            placeholder="Ulice, Město" 
                            className="flex-1 bg-slate-800 rounded-xl p-3 text-sm text-white border-none" 
                        />
                        <button 
                            onClick={() => openMap(currentTask.to)}
                            className="bg-slate-800 text-blue-400 p-3 rounded-xl hover:bg-slate-700 transition-colors border border-slate-700"
                            title="Otevřít v mapách"
                        >
                            <Icons.Map />
                        </button>
                    </div>
                </div>
              </div>

              <div className="space-y-3">
                <label className="text-xs font-black text-white uppercase px-1">Tým (kliknutím vyber)</label>
                <div className="flex flex-wrap gap-2">
                   {workers.map(w => (
                     <button key={w.id} onClick={() => toggleResource(w.id, 'worker')} className={`px-4 py-2 rounded-xl text-xs font-black transition-all border ${currentTask.assignedWorkers?.includes(w.id) ? 'bg-blue-600 border-blue-500 text-white shadow-lg' : 'bg-slate-800 border-slate-700 text-white'}`}>{w.name}</button>
                   ))}
                </div>
              </div>

              <div className="space-y-3">
                <label className="text-xs font-black text-white uppercase px-1">Vozidla (kliknutím vyber)</label>
                <div className="flex flex-wrap gap-2">
                   {vehicles.map(v => (
                     <button key={v.id} onClick={() => toggleResource(v.id, 'vehicle')} className={`px-4 py-2 rounded-xl text-xs font-black transition-all border ${currentTask.assignedVehicles?.includes(v.id) ? 'bg-red-600 border-red-500 text-white shadow-lg' : 'bg-slate-800 border-slate-700 text-white'}`}>{v.plate}</button>
                   ))}
                </div>
              </div>

              {/* Sekce Poznámky s AI funkcí */}
              <div className="space-y-2 pt-2 border-t border-slate-800/50">
                <div className="flex items-center justify-between">
                    <label className="text-xs font-black text-white uppercase px-1">Poznámky</label>
                    <button 
                        onClick={parseNotesAndFill}
                        disabled={isAnalyzing}
                        className={`text-[9px] font-black uppercase tracking-widest px-3 py-1 rounded-full transition-colors flex items-center gap-1 ${isAnalyzing ? 'bg-slate-700 text-slate-400 cursor-not-allowed' : 'bg-blue-900/20 text-blue-400 hover:bg-blue-900/40'}`}
                    >
                        {isAnalyzing ? (
                          <>
                            <div className="w-2 h-2 border-2 border-slate-400 border-t-transparent rounded-full animate-spin"></div> Analyzuji...
                          </>
                        ) : (
                          <>
                            <Icons.Sparkles /> Rozpoznat údaje (AI)
                          </>
                        )}
                    </button>
                </div>
                <textarea 
                    value={currentTask.notes || ''} 
                    onChange={e => setCurrentTask({...currentTask, notes: e.target.value})} 
                    placeholder="Vložte text, např.: 'Karel Novák, 777123456, Nakládka: Praha 1, Vykládka: Brno'"
                    className="w-full bg-slate-800 rounded-xl p-4 text-sm text-white border-none min-h-[120px]"
                    rows={5}
                />
                <p className="text-[9px] text-slate-600 px-1">
                    Tip: Zkopírujte sem text emailu a klikněte na "Rozpoznat údaje" pro automatické vyplnění polí pomocí Gemini AI.
                </p>
              </div>

              <div className="flex gap-4 pt-4">
                <button onClick={() => setShowModal(false)} className="flex-1 text-slate-500 font-black uppercase text-xs tracking-widest">Zrušit</button>
                <button onClick={saveTask} className="flex-[2] bg-blue-600 text-white font-black py-4 rounded-2xl shadow-xl shadow-blue-600/20 uppercase text-xs tracking-widest">Uložit změny</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CalendarView;

import React, { useState, useMemo } from 'react';
import { MoveTask, Worker, Vehicle } from '../types';
import { Icons, COLORS } from '../constants';
import { geminiService } from '../services/geminiService';

interface CalendarViewProps {
  tasks: MoveTask[];
  setTasks: React.Dispatch<React.SetStateAction<MoveTask[]>>;
  workers: Worker[];
  vehicles: Vehicle[];
  user: { role: 'admin' | 'user' };
}

type ViewMode = 'day' | 'week';

const CalendarView: React.FC<CalendarViewProps> = ({ tasks, setTasks, workers, vehicles, user }) => {
  const [viewMode, setViewMode] = useState<ViewMode>('day');
  const [currentDate, setCurrentDate] = useState(new Date());
  const [showModal, setShowModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  const [currentTask, setCurrentTask] = useState<Partial<MoveTask>>({
    title: '', customer: '', customerPhone: '', from: '', to: '',
    status: 'Pending', notes: '', assignedWorkers: [], assignedVehicles: []
  });

  const isSameDay = (d1: Date, d2: Date) => 
    d1.getFullYear() === d2.getFullYear() &&
    d1.getMonth() === d2.getMonth() &&
    d1.getDate() === d2.getDate();

  const getMonday = (d: Date) => {
    const date = new Date(d);
    const day = date.getDay();
    const diff = date.getDate() - day + (day === 0 ? -6 : 1); 
    return new Date(date.setDate(diff));
  };

  const navigateDate = (direction: 'prev' | 'next') => {
    const newDate = new Date(currentDate);
    if (viewMode === 'day') {
      newDate.setDate(currentDate.getDate() + (direction === 'next' ? 1 : -1));
    } else {
      newDate.setDate(currentDate.getDate() + (direction === 'next' ? 7 : -7));
    }
    setCurrentDate(newDate);
  };

  const START_HOUR = 6;
  const END_HOUR = 22;
  const HOUR_HEIGHT = 90;

  const handleOpenCreate = () => {
    setIsEditing(false);
    const start = new Date(currentDate);
    start.setHours(9, 0, 0, 0);
    const end = new Date(start.getTime() + 3 * 60 * 60 * 1000);
    setCurrentTask({
      title: '', customer: '', customerPhone: '', from: '', to: '',
      status: 'Pending', start, end, assignedWorkers: [], assignedVehicles: [], notes: ''
    });
    setShowModal(true);
  };

  const handleOpenEdit = (task: MoveTask) => {
    setIsEditing(true);
    setCurrentTask({ ...task });
    setShowModal(true);
  };

  const saveTask = () => {
    if (!currentTask.title || !currentTask.start || !currentTask.end) return;
    const taskData = {
      ...currentTask,
      id: currentTask.id || Math.random().toString(36).substr(2, 9),
      start: new Date(currentTask.start),
      end: new Date(currentTask.end)
    } as MoveTask;

    if (isEditing) {
      setTasks(tasks.map(t => t.id === taskData.id ? taskData : t));
    } else {
      setTasks([...tasks, taskData]);

      // --- AUTOMATICKÁ NOTIFIKACE (SMS - HROMADNÁ) ---
      // Pokud je to nová zakázka, pošli SMS všem přiřazeným pracovníkům
      const assignedTeam = workers.filter(w => w.id && taskData.assignedWorkers.includes(w.id));

      if (assignedTeam.length > 0) {
        // Získat všechna telefonní čísla oddělená čárkou (standard pro hromadné SMS)
        const recipients = assignedTeam
            .map(w => w.phone.replace(/\s+/g, '')) // Odstranit mezery
            .filter(p => p.length > 0)
            .join(',');

        const dateStr = taskData.start.toLocaleDateString('cs-CZ');
        const timeStr = taskData.start.toLocaleTimeString('cs-CZ', { hour: '2-digit', minute: '2-digit' });

        // Formátování pro SMS (bez Markdownu, stručné)
        const msg = `🚚 NOVÁ ZAKÁZKA: ${taskData.title}\n` +
                    `📅 ${dateStr} v ${timeStr}\n` +
                    `📍 Z: ${taskData.from}\n` +
                    `🏁 Do: ${taskData.to}\n` +
                    `👤 Klient: ${taskData.customer}\n` +
                    `📞 ${taskData.customerPhone}\n` +
                    `📝 ${taskData.notes || ''}`;

        setTimeout(() => {
            // Otevření nativní aplikace Zprávy s předvyplněnými čísly a textem
            // 'sms:' schéma s oddělovačem čárkou funguje na většině Androidů i iOS pro hromadné zprávy
            window.open(`sms:${recipients}?body=${encodeURIComponent(msg)}`, '_self');
        }, 300);
      }
      // ----------------------------------------
    }
    setShowModal(false);
  };

  const toggleResource = (id: string, type: 'worker' | 'vehicle') => {
    if (type === 'worker') {
      const current = currentTask.assignedWorkers || [];
      const updated = current.includes(id) ? current.filter(wid => wid !== id) : [...current, id];
      setCurrentTask({...currentTask, assignedWorkers: updated});
    } else {
      const current = currentTask.assignedVehicles || [];
      const updated = current.includes(id) ? current.filter(vid => vid !== id) : [...current, id];
      setCurrentTask({...currentTask, assignedVehicles: updated});
    }
  };

  const formatForInput = (date?: Date) => {
    if (!date) return '';
    const d = new Date(date);
    d.setMinutes(d.getMinutes() - d.getTimezoneOffset());
    return d.toISOString().slice(0, 16);
  };

  const openMap = (address?: string) => {
    if (!address) return;
    window.open(`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(address)}`, '_blank');
  };

  // Funkce pro chytré rozpoznání údajů z poznámky pomocí AI
  const parseNotesAndFill = async () => {
    if (!currentTask.notes || isAnalyzing) return;

    setIsAnalyzing(true);
    try {
      const extractedData = await geminiService.extractTaskFromNotes(currentTask.notes);

      const updates: Partial<MoveTask> = {};
      if (extractedData.title) updates.title = extractedData.title;
      if (extractedData.customer) updates.customer = extractedData.customer;
      if (extractedData.customerPhone) updates.customerPhone = extractedData.customerPhone;
      if (extractedData.from) updates.from = extractedData.from;
      if (extractedData.to) updates.to = extractedData.to;

      // Aplikace změn pouze pro nevyplněná pole nebo přepis
      setCurrentTask(prev => ({ ...prev, ...updates }));
    } catch (e) {
      console.error("Chyba při AI analýze:", e);
      alert("Nepodařilo se automaticky rozpoznat údaje. Zkontrolujte připojení nebo API klíč.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const renderDayView = () => {
    const dayTasks = tasks.filter(task => isSameDay(task.start, currentDate));
    return (
      <div className="flex-1 overflow-y-auto no-scrollbar relative p-5 md:p-8 pt-4 bg-slate-900">
        <div className="absolute left-4 top-4 bottom-0 w-12 z-10 pointer-events-none text-slate-700 text-[10px] md:text-xs font-black">
          {Array.from({ length: END_HOUR - START_HOUR + 1 }).map((_, i) => (
            <div key={i} style={{ height: `${HOUR_HEIGHT}px` }}>{START_HOUR + i}:00</div>
          ))}
        </div>
        <div className="ml-14 relative h-full min-h-[1440px]">
           {Array.from({ length: END_HOUR - START_HOUR + 1 }).map((_, i) => (
             <div key={i} className="border-t border-slate-800 absolute w-full pointer-events-none" style={{ top: `${i * HOUR_HEIGHT}px` }} />
           ))}
           {isSameDay(currentDate, new Date()) && (
              <div className="absolute left-0 right-0 border-t-2 border-red-500 z-10 flex items-center pointer-events-none" style={{ top: `${(new Date().getHours() - START_HOUR + new Date().getMinutes()/60) * HOUR_HEIGHT}px` }}>
                <div className="w-2 h-2 rounded-full bg-red-500 -ml-1 shadow-[0_0_10px_#ef4444]" />
              </div>
            )}
           {dayTasks.map(task => {
             const startHour = task.start.getHours() + task.start.getMinutes()/60;
             const endHour = task.end.getHours() + task.end.getMinutes()/60;
             const top = (startHour - START_HOUR) * HOUR_HEIGHT;
             const height = (endHour - startHour) * HOUR_HEIGHT;
             return (
               <div key={task.id} onClick={() => handleOpenEdit(task)} className="absolute w-full p-1 z-20" style={{ top: `${top}px`, height: `${height}px` }}>
                 <div className={`h-full w-full rounded-2xl border p-4 shadow-lg flex flex-col justify-between overflow-hidden ${task.status === 'Confirmed' ? 'bg-blue-600 border-blue-500 text-white' : 'bg-red-600 border-red-500 text-white'}`}>
                   <div>
                     <h4 className="text-xs md:text-lg font-black leading-none truncate">{task.title}</h4>
                     <p className="text-[9px] md:text-sm font-bold opacity-70 uppercase mt-1 truncate">{task.customer}</p>
                   </div>
                   <p className="text-[8px] md:text-xs font-black uppercase text-right opacity-60">{task.start.getHours()}:{task.start.getMinutes().toString().padStart(2, '0')}</p>
                 </div>
               </div>
             );
           })}
        </div>
      </div>
    );
  };

  const renderWeekView = () => {
    const monday = getMonday(currentDate);
    const weekDays = Array.from({ length: 7 }).map((_, i) => {
      const d = new Date(monday);
      d.setDate(monday.getDate() + i);
      return d;
    });

    return (
      <div className="flex-1 overflow-y-auto no-scrollbar p-5 md:p-8 space-y-4 bg-slate-900">
        {weekDays.map((day, idx) => {
          const dayTasks = tasks.filter(t => isSameDay(t.start, day));
          const isToday = isSameDay(day, new Date());
          return (
            <div key={idx} className={`bg-slate-800 rounded-3xl p-5 border-2 transition-all ${isToday ? 'border-red-600 shadow-[0_0_20px_rgba(220,38,38,0.1)]' : 'border-slate-700'}`}>
              <div className="flex justify-between items-center mb-4">
                <div>
                  <h4 className={`text-sm md:text-lg font-black uppercase tracking-widest ${isToday ? 'text-red-500' : 'text-slate-100'}`}>
                    {day.toLocaleDateString('cs-CZ', { weekday: 'long' })}
                  </h4>
                  <p className="text-[10px] md:text-sm font-bold text-slate-500 mt-0.5">{day.toLocaleDateString('cs-CZ', { day: 'numeric', month: 'long' })}</p>
                </div>
                {dayTasks.length > 0 && <span className="bg-slate-900 text-blue-400 text-[10px] md:text-xs font-black px-3 py-1 rounded-full border border-slate-700">{dayTasks.length} akce</span>}
              </div>

              <div className="space-y-2">
                {dayTasks.length > 0 ? dayTasks.map(task => (
                  <div key={task.id} onClick={() => handleOpenEdit(task)} className="bg-slate-900/50 p-3 md:p-4 rounded-xl border border-slate-700/50 flex items-center justify-between group cursor-pointer hover:bg-slate-900 transition-all">
                    <div className="flex items-center gap-3">
                      <div className={`w-1.5 h-1.5 md:w-2 md:h-2 rounded-full ${task.status === 'Confirmed' ? 'bg-blue-500' : 'bg-red-500'}`} />
                      <div>
                        <p className="text-xs md:text-base font-bold text-slate-200 group-hover:text-blue-400 transition-colors">{task.title}</p>
                        <p className="text-[9px] md:text-xs text-slate-500 font-black uppercase">{task.customer}</p>
                      </div>
                    </div>
                    <span className="text-[10px] md:text-sm font-black text-slate-600">{task.start.getHours()}:{task.start.getMinutes().toString().padStart(2, '0')}</span>
                  </div>
                )) : (
                  <p className="text-[10px] md:text-xs text-slate-600 italic font-medium px-1">Žádné zakázky na tento den.</p>
                )}
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  const getNavigationLabel = () => {
    if (viewMode === 'day') {
      return currentDate.toLocaleDateString('cs-CZ', { day: 'numeric', month: 'long' });
    } else {
      const monday = getMonday(currentDate);
      const sunday = new Date(monday);
      sunday.setDate(monday.getDate() + 6);
      return `${monday.getDate()}. - ${sunday.getDate()}. ${sunday.toLocaleDateString('cs-CZ', { month: 'long' })}`;
    }
  };

  return (
    <div className="space-y-6">
      {/* View Switcher */}
      <div className="flex items-center justify-between">
        <div className="flex bg-slate-900 p-1 rounded-2xl border border-slate-800 shadow-inner">
          <button 
            onClick={() => setViewMode('day')}
            className={`px-6 py-2 rounded-xl text-[10px] md:text-sm font-black uppercase tracking-widest transition-all ${viewMode === 'day' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-600 hover:text-slate-400'}`}
          >
            Den
          </button>
          <button 
            onClick={() => setViewMode('week')}
            className={`px-6 py-2 rounded-xl text-[10px] md:text-sm font-black uppercase tracking-widest transition-all ${viewMode === 'week' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-600 hover:text-slate-400'}`}
          >
            Týden
          </button>
        </div>
        {user.role === 'admin' && (
          <button onClick={handleOpenCreate} className="bg-red-600 text-white p-3 md:p-4 rounded-2xl shadow-xl shadow-red-600/30 active:scale-95 transition-all">
            <Icons.Plus />
          </button>
        )}
      </div>

      {/* Navigation */}
      <div className="bg-slate-800 rounded-[2rem] p-5 shadow-sm border border-slate-700 flex items-center justify-between">
        <button onClick={() => navigateDate('prev')} className="p-3 text-slate-500 hover:text-white transition-colors">
          <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round"><path d="m15 18-6-6 6-6"/></svg>
        </button>
        <div className="text-center">
          <p className="text-xs md:text-lg font-black text-slate-100 uppercase tracking-widest">
            {getNavigationLabel()}
          </p>
          {viewMode === 'day' && <p className="text-[10px] md:text-sm font-bold text-red-500 uppercase tracking-widest mt-0.5">{currentDate.toLocaleDateString('cs-CZ', { weekday: 'long' })}</p>}
          {viewMode === 'week' && <p className="text-[10px] md:text-sm font-bold text-blue-500 uppercase tracking-widest mt-0.5">Týdenní přehled</p>}
        </div>
        <button onClick={() => navigateDate('next')} className="p-3 text-slate-500 hover:text-white transition-colors">
          <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round"><path d="m9 18 6-6-6-6"/></svg>
        </button>
      </div>

      {/* Main Content Area */}
      <div className="bg-slate-800 rounded-[3rem] shadow-sm border border-slate-700 overflow-hidden flex flex-col h-[600px] md:h-[800px] relative">
        {viewMode === 'day' ? renderDayView() : renderWeekView()}
      </div>

      {/* Task Edit Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-slate-950/95 backdrop-blur-lg z-50 flex items-end sm:items-center justify-center p-4">
          <div className="bg-slate-900 w-full max-w-lg rounded-[32px] p-8 border border-slate-800 animate-slide-up max-h-[90vh] overflow-y-auto no-scrollbar shadow-2xl">
            <h3 className="text-2xl font-black text-white mb-6 uppercase tracking-tighter">{isEditing ? 'Upravit zakázku' : 'Nová zakázka'}</h3>
            <div className="space-y-6">
              <div className="space-y-1">
                <label className="text-xs font-black text-white uppercase px-1">Název akce</label>
                <input value={currentTask.title} onChange={e => setCurrentTask({...currentTask, title: e.target.value})} placeholder="např. Stěhování bytu 3+1" className="w-full bg-slate-800 rounded-xl p-4 text-white border-none font-bold" />
              </div>
              <div className="grid grid-cols-2 gap-4">
                 <div className="space-y-1">
                    <label className="text-xs font-black text-white uppercase px-1">Zákazník</label>
                    <input value={currentTask.customer} onChange={e => setCurrentTask({...currentTask, customer: e.target.value})} className="w-full bg-slate-800 rounded-xl p-3 text-sm text-white border-none" />
                 </div>
                 <div className="space-y-1">
                    <label className="text-xs font-black text-white uppercase px-1">Telefon</label>
                    <input value={currentTask.customerPhone} onChange={e => setCurrentTask({...currentTask, customerPhone: e.target.value})} className="w-full bg-slate-800 rounded-xl p-3 text-sm text-white border-none" />
                 </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                 <div className="space-y-1">
                    <label className="text-xs font-black text-white uppercase px-1">Začátek</label>
                    <input type="datetime-local" value={formatForInput(currentTask.start)} onChange={e => setCurrentTask({...currentTask, start: new Date(e.target.value)})} className="w-full bg-slate-800 rounded-xl p-3 text-xs text-white border-none" />
                 </div>
                 <div className="space-y-1">
                    <label className="text-xs font-black text-white uppercase px-1">Konec</label>
                    <input type="datetime-local" value={formatForInput(currentTask.end)} onChange={e => setCurrentTask({...currentTask, end: new Date(e.target.value)})} className="w-full bg-slate-800 rounded-xl p-3 text-xs text-white border-none" />
                 </div>
              </div>

              {/* Adresní pole bez sekce Logistika */}
              <div className="space-y-3">
                <div className="space-y-1">
                    <label className="text-xs font-black text-white uppercase px-1">Nakládka (Odkud)</label>
                    <div className="flex gap-2">
                        <input 
                            value={currentTask.from} 
                            onChange={e => setCurrentTask({...currentTask, from: e.target.value})} 
                            placeholder="Ulice, Město" 
                            className="flex-1 bg-slate-800 rounded-xl p-3 text-sm text-white border-none" 
                        />
                        <button 
                            onClick={() => openMap(currentTask.from)}
                            className="bg-slate-800 text-blue-400 p-3 rounded-xl hover:bg-slate-700 transition-colors border border-slate-700"
                            title="Otevřít v mapách"
                        >
                            <Icons.Map />
                        </button>
                    </div>
                </div>
                <div className="space-y-1">
                    <label className="text-xs font-black text-white uppercase px-1">Vykládka (Kam)</label>
                    <div className="flex gap-2">
                        <input 
                            value={currentTask.to} 
                            onChange={e => setCurrentTask({...currentTask, to: e.target.value})} 
                            placeholder="Ulice, Město" 
                            className="flex-1 bg-slate-800 rounded-xl p-3 text-sm text-white border-none" 
                        />
                        <button 
                            onClick={() => openMap(currentTask.to)}
                            className="bg-slate-800 text-blue-400 p-3 rounded-xl hover:bg-slate-700 transition-colors border border-slate-700"
                            title="Otevřít v mapách"
                        >
                            <Icons.Map />
                        </button>
                    </div>
                </div>
              </div>

              <div className="space-y-3">
                <label className="text-xs font-black text-white uppercase px-1">Tým (kliknutím vyber)</label>
                <div className="flex flex-wrap gap-2">
                   {workers.map(w => (
                     <button key={w.id} onClick={() => toggleResource(w.id, 'worker')} className={`px-4 py-2 rounded-xl text-xs font-black transition-all border ${currentTask.assignedWorkers?.includes(w.id) ? 'bg-blue-600 border-blue-500 text-white shadow-lg' : 'bg-slate-800 border-slate-700 text-white'}`}>{w.name}</button>
                   ))}
                </div>
              </div>

              <div className="space-y-3">
                <label className="text-xs font-black text-white uppercase px-1">Vozidla (kliknutím vyber)</label>
                <div className="flex flex-wrap gap-2">
                   {vehicles.map(v => (
                     <button 
                        key={v.id} 
                        onClick={() => toggleResource(v.id, 'vehicle')} 
                        className={`px-4 py-2 rounded-xl transition-all border flex flex-col items-center ${currentTask.assignedVehicles?.includes(v.id) ? 'bg-red-600 border-red-500 text-white shadow-lg' : 'bg-slate-800 border-slate-700 text-white'}`}
                    >
                        <span className="text-xs font-black">{v.model}</span>
                        <span className="text-[8px] opacity-60 font-bold uppercase tracking-wider">{v.plate}</span>
                    </button>
                   ))}
                </div>
              </div>

              {/* Sekce Poznámky s AI funkcí */}
              <div className="space-y-2 pt-2 border-t border-slate-800/50">
                <div className="flex items-center justify-between">
                    <label className="text-xs font-black text-white uppercase px-1">Poznámky</label>
                    <button 
                        onClick={parseNotesAndFill}
                        disabled={isAnalyzing}
                        className={`text-[9px] font-black uppercase tracking-widest px-3 py-1 rounded-full transition-colors flex items-center gap-1 ${isAnalyzing ? 'bg-slate-700 text-slate-400 cursor-not-allowed' : 'bg-blue-900/20 text-blue-400 hover:bg-blue-900/40'}`}
                    >
                        {isAnalyzing ? (
                          <>
                            <div className="w-2 h-2 border-2 border-slate-400 border-t-transparent rounded-full animate-spin"></div> Analyzuji...
                          </>
                        ) : (
                          <>
                            <Icons.Sparkles /> Rozpoznat údaje (AI)
                          </>
                        )}
                    </button>
                </div>
                <textarea 
                    value={currentTask.notes || ''} 
                    onChange={e => setCurrentTask({...currentTask, notes: e.target.value})} 
                    placeholder="Vložte text, např.: 'Karel Novák, 777123456, Nakládka: Praha 1, Vykládka: Brno'"
                    className="w-full bg-slate-800 rounded-xl p-4 text-sm text-white border-none min-h-[120px]"
                    rows={5}
                />
                <p className="text-[9px] text-slate-600 px-1">
                    Tip: Zkopírujte sem text emailu a klikněte na "Rozpoznat údaje" pro automatické vyplnění polí pomocí Gemini AI.
                </p>
              </div>

              <div className="flex gap-4 pt-4">
                <button onClick={() => setShowModal(false)} className="flex-1 text-slate-500 font-black uppercase text-xs tracking-widest">Zrušit</button>
                <button onClick={saveTask} className="flex-[2] bg-blue-600 text-white font-black py-4 rounded-2xl shadow-xl shadow-blue-600/20 uppercase text-xs tracking-widest">Uložit změny</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CalendarView;

import React, { useState, useMemo } from 'react';
import { MoveTask, Worker, Vehicle } from '../types';
import { Icons, COLORS } from '../constants';
import { geminiService } from '../services/geminiService';

interface CalendarViewProps {
  tasks: MoveTask[];
  setTasks: React.Dispatch<React.SetStateAction<MoveTask[]>>;
  workers: Worker[];
  vehicles: Vehicle[];
  user: { role: 'admin' | 'user' };
}

type ViewMode = 'day' | 'week';

const CalendarView: React.FC<CalendarViewProps> = ({ tasks, setTasks, workers, vehicles, user }) => {
  const [viewMode, setViewMode] = useState<ViewMode>('day');
  const [currentDate, setCurrentDate] = useState(new Date());
  const [showModal, setShowModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  const [currentTask, setCurrentTask] = useState<Partial<MoveTask>>({
    title: '', customer: '', customerPhone: '', from: '', to: '',
    status: 'Pending', notes: '', assignedWorkers: [], assignedVehicles: []
  });

  const isSameDay = (d1: Date, d2: Date) => 
    d1.getFullYear() === d2.getFullYear() &&
    d1.getMonth() === d2.getMonth() &&
    d1.getDate() === d2.getDate();

  const getMonday = (d: Date) => {
    const date = new Date(d);
    const day = date.getDay();
    const diff = date.getDate() - day + (day === 0 ? -6 : 1); 
    return new Date(date.setDate(diff));
  };

  const navigateDate = (direction: 'prev' | 'next') => {
    const newDate = new Date(currentDate);
    if (viewMode === 'day') {
      newDate.setDate(currentDate.getDate() + (direction === 'next' ? 1 : -1));
    } else {
      newDate.setDate(currentDate.getDate() + (direction === 'next' ? 7 : -7));
    }
    setCurrentDate(newDate);
  };

  const START_HOUR = 6;
  const END_HOUR = 22;
  const HOUR_HEIGHT = 90;

  const handleOpenCreate = () => {
    setIsEditing(false);
    const start = new Date(currentDate);
    start.setHours(9, 0, 0, 0);
    const end = new Date(start.getTime() + 3 * 60 * 60 * 1000);
    setCurrentTask({
      title: '', customer: '', customerPhone: '', from: '', to: '',
      status: 'Pending', start, end, assignedWorkers: [], assignedVehicles: [], notes: ''
    });
    setShowModal(true);
  };

  const handleOpenEdit = (task: MoveTask) => {
    setIsEditing(true);
    setCurrentTask({ ...task });
    setShowModal(true);
  };

  const saveTask = () => {
    if (!currentTask.title || !currentTask.start || !currentTask.end) return;
    const taskData = {
      ...currentTask,
      id: currentTask.id || Math.random().toString(36).substr(2, 9),
      start: new Date(currentTask.start),
      end: new Date(currentTask.end)
    } as MoveTask;

    if (isEditing) {
      setTasks(tasks.map(t => t.id === taskData.id ? taskData : t));
    } else {
      setTasks([...tasks, taskData]);

      // --- AUTOMATICKÁ NOTIFIKACE (SMS - HROMADNÁ) ---
      // Pokud je to nová zakázka, pošli SMS všem přiřazeným pracovníkům
      const assignedTeam = workers.filter(w => w.id && taskData.assignedWorkers.includes(w.id));

      if (assignedTeam.length > 0) {
        // Získat všechna telefonní čísla oddělená čárkou (standard pro hromadné SMS)
        const recipients = assignedTeam
            .map(w => w.phone.replace(/\s+/g, '')) // Odstranit mezery
            .filter(p => p.length > 0)
            .join(',');

        const dateStr = taskData.start.toLocaleDateString('cs-CZ');
        const timeStr = taskData.start.toLocaleTimeString('cs-CZ', { hour: '2-digit', minute: '2-digit' });

        // Formátování pro SMS (bez Markdownu, stručné)
        const msg = `🚚 NOVÁ ZAKÁZKA: ${taskData.title}\n` +
                    `📅 ${dateStr} v ${timeStr}\n` +
                    `📍 Z: ${taskData.from}\n` +
                    `🏁 Do: ${taskData.to}\n` +
                    `👤 Klient: ${taskData.customer}\n` +
                    `📞 ${taskData.customerPhone}\n` +
                    `📝 ${taskData.notes || ''}`;

        setTimeout(() => {
            // Otevření nativní aplikace Zprávy s předvyplněnými čísly a textem
            // 'sms:' schéma s oddělovačem čárkou funguje na většině Androidů i iOS pro hromadné zprávy
            window.open(`sms:${recipients}?body=${encodeURIComponent(msg)}`, '_self');
        }, 300);
      }
      // ----------------------------------------
    }
    setShowModal(false);
  };

  const toggleResource = (id: string, type: 'worker' | 'vehicle') => {
    if (type === 'worker') {
      const current = currentTask.assignedWorkers || [];
      const updated = current.includes(id) ? current.filter(wid => wid !== id) : [...current, id];
      setCurrentTask({...currentTask, assignedWorkers: updated});
    } else {
      const current = currentTask.assignedVehicles || [];
      const updated = current.includes(id) ? current.filter(vid => vid !== id) : [...current, id];
      setCurrentTask({...currentTask, assignedVehicles: updated});
    }
  };

  const formatForInput = (date?: Date) => {
    if (!date) return '';
    const d = new Date(date);
    d.setMinutes(d.getMinutes() - d.getTimezoneOffset());
    return d.toISOString().slice(0, 16);
  };

  const openMap = (address?: string) => {
    if (!address) return;
    window.open(`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(address)}`, '_blank');
  };

  // Funkce pro chytré rozpoznání údajů z poznámky pomocí AI
  const parseNotesAndFill = async () => {
    if (!currentTask.notes || isAnalyzing) return;

    setIsAnalyzing(true);
    try {
      const extractedData = await geminiService.extractTaskFromNotes(currentTask.notes);

      const updates: Partial<MoveTask> = {};
      if (extractedData.title) updates.title = extractedData.title;
      if (extractedData.customer) updates.customer = extractedData.customer;
      if (extractedData.customerPhone) updates.customerPhone = extractedData.customerPhone;
      if (extractedData.from) updates.from = extractedData.from;
      if (extractedData.to) updates.to = extractedData.to;

      // Aplikace změn pouze pro nevyplněná pole nebo přepis
      setCurrentTask(prev => ({ ...prev, ...updates }));
    } catch (e) {
      console.error("Chyba při AI analýze:", e);
      alert("Nepodařilo se automaticky rozpoznat údaje. Zkontrolujte připojení nebo API klíč.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const renderDayView = () => {
    const dayTasks = tasks.filter(task => isSameDay(task.start, currentDate));
    return (
      <div className="flex-1 overflow-y-auto no-scrollbar relative p-5 md:p-8 pt-4 bg-slate-900">
        <div className="absolute left-4 top-4 bottom-0 w-12 z-10 pointer-events-none text-slate-700 text-[10px] md:text-xs font-black">
          {Array.from({ length: END_HOUR - START_HOUR + 1 }).map((_, i) => (
            <div key={i} style={{ height: `${HOUR_HEIGHT}px` }}>{START_HOUR + i}:00</div>
          ))}
        </div>
        <div className="ml-14 relative h-full min-h-[1440px]">
           {Array.from({ length: END_HOUR - START_HOUR + 1 }).map((_, i) => (
             <div key={i} className="border-t border-slate-800 absolute w-full pointer-events-none" style={{ top: `${i * HOUR_HEIGHT}px` }} />
           ))}
           {isSameDay(currentDate, new Date()) && (
              <div className="absolute left-0 right-0 border-t-2 border-red-500 z-10 flex items-center pointer-events-none" style={{ top: `${(new Date().getHours() - START_HOUR + new Date().getMinutes()/60) * HOUR_HEIGHT}px` }}>
                <div className="w-2 h-2 rounded-full bg-red-500 -ml-1 shadow-[0_0_10px_#ef4444]" />
              </div>
            )}
           {dayTasks.map(task => {
             const startHour = task.start.getHours() + task.start.getMinutes()/60;
             const endHour = task.end.getHours() + task.end.getMinutes()/60;
             const top = (startHour - START_HOUR) * HOUR_HEIGHT;
             const height = (endHour - startHour) * HOUR_HEIGHT;
             return (
               <div key={task.id} onClick={() => handleOpenEdit(task)} className="absolute w-full p-1 z-20" style={{ top: `${top}px`, height: `${height}px` }}>
                 <div className={`h-full w-full rounded-2xl border p-4 shadow-lg flex flex-col justify-between overflow-hidden ${task.status === 'Confirmed' ? 'bg-blue-600 border-blue-500 text-white' : 'bg-red-600 border-red-500 text-white'}`}>
                   <div>
                     <h4 className="text-xs md:text-lg font-black leading-none truncate">{task.title}</h4>
                     <p className="text-[9px] md:text-sm font-bold opacity-70 uppercase mt-1 truncate">{task.customer}</p>
                   </div>
                   <p className="text-[8px] md:text-xs font-black uppercase text-right opacity-60">{task.start.getHours()}:{task.start.getMinutes().toString().padStart(2, '0')}</p>
                 </div>
               </div>
             );
           })}
        </div>
      </div>
    );
  };

  const renderWeekView = () => {
    const monday = getMonday(currentDate);
    const weekDays = Array.from({ length: 7 }).map((_, i) => {
      const d = new Date(monday);
      d.setDate(monday.getDate() + i);
      return d;
    });

    return (
      <div className="flex-1 overflow-y-auto no-scrollbar p-5 md:p-8 space-y-4 bg-slate-900">
        {weekDays.map((day, idx) => {
          const dayTasks = tasks.filter(t => isSameDay(t.start, day));
          const isToday = isSameDay(day, new Date());
          return (
            <div key={idx} className={`bg-slate-800 rounded-3xl p-5 border-2 transition-all ${isToday ? 'border-red-600 shadow-[0_0_20px_rgba(220,38,38,0.1)]' : 'border-slate-700'}`}>
              <div className="flex justify-between items-center mb-4">
                <div>
                  <h4 className={`text-sm md:text-lg font-black uppercase tracking-widest ${isToday ? 'text-red-500' : 'text-slate-100'}`}>
                    {day.toLocaleDateString('cs-CZ', { weekday: 'long' })}
                  </h4>
                  <p className="text-[10px] md:text-sm font-bold text-slate-500 mt-0.5">{day.toLocaleDateString('cs-CZ', { day: 'numeric', month: 'long' })}</p>
                </div>
                {dayTasks.length > 0 && <span className="bg-slate-900 text-blue-400 text-[10px] md:text-xs font-black px-3 py-1 rounded-full border border-slate-700">{dayTasks.length} akce</span>}
              </div>

              <div className="space-y-2">
                {dayTasks.length > 0 ? dayTasks.map(task => (
                  <div key={task.id} onClick={() => handleOpenEdit(task)} className="bg-slate-900/50 p-3 md:p-4 rounded-xl border border-slate-700/50 flex items-center justify-between group cursor-pointer hover:bg-slate-900 transition-all">
                    <div className="flex items-center gap-3">
                      <div className={`w-1.5 h-1.5 md:w-2 md:h-2 rounded-full ${task.status === 'Confirmed' ? 'bg-blue-500' : 'bg-red-500'}`} />
                      <div>
                        <p className="text-xs md:text-base font-bold text-slate-200 group-hover:text-blue-400 transition-colors">{task.title}</p>
                        <p className="text-[9px] md:text-xs text-slate-500 font-black uppercase">{task.customer}</p>
                      </div>
                    </div>
                    <span className="text-[10px] md:text-sm font-black text-slate-600">{task.start.getHours()}:{task.start.getMinutes().toString().padStart(2, '0')}</span>
                  </div>
                )) : (
                  <p className="text-[10px] md:text-xs text-slate-600 italic font-medium px-1">Žádné zakázky na tento den.</p>
                )}
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  const getNavigationLabel = () => {
    if (viewMode === 'day') {
      return currentDate.toLocaleDateString('cs-CZ', { day: 'numeric', month: 'long' });
    } else {
      const monday = getMonday(currentDate);
      const sunday = new Date(monday);
      sunday.setDate(monday.getDate() + 6);
      return `${monday.getDate()}. - ${sunday.getDate()}. ${sunday.toLocaleDateString('cs-CZ', { month: 'long' })}`;
    }
  };

  return (
    <div className="space-y-6">
      {/* View Switcher */}
      <div className="flex items-center justify-between">
        <div className="flex bg-slate-900 p-1 rounded-2xl border border-slate-800 shadow-inner">
          <button 
            onClick={() => setViewMode('day')}
            className={`px-6 py-2 rounded-xl text-[10px] md:text-sm font-black uppercase tracking-widest transition-all ${viewMode === 'day' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-600 hover:text-slate-400'}`}
          >
            Den
          </button>
          <button 
            onClick={() => setViewMode('week')}
            className={`px-6 py-2 rounded-xl text-[10px] md:text-sm font-black uppercase tracking-widest transition-all ${viewMode === 'week' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-600 hover:text-slate-400'}`}
          >
            Týden
          </button>
        </div>
        {user.role === 'admin' && (
          <button onClick={handleOpenCreate} className="bg-red-600 text-white p-3 md:p-4 rounded-2xl shadow-xl shadow-red-600/30 active:scale-95 transition-all">
            <Icons.Plus />
          </button>
        )}
      </div>

      {/* Navigation */}
      <div className="bg-slate-800 rounded-[2rem] p-5 shadow-sm border border-slate-700 flex items-center justify-between">
        <button onClick={() => navigateDate('prev')} className="p-3 text-slate-500 hover:text-white transition-colors">
          <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round"><path d="m15 18-6-6 6-6"/></svg>
        </button>
        <div className="text-center">
          <p className="text-xs md:text-lg font-black text-slate-100 uppercase tracking-widest">
            {getNavigationLabel()}
          </p>
          {viewMode === 'day' && <p className="text-[10px] md:text-sm font-bold text-red-500 uppercase tracking-widest mt-0.5">{currentDate.toLocaleDateString('cs-CZ', { weekday: 'long' })}</p>}
          {viewMode === 'week' && <p className="text-[10px] md:text-sm font-bold text-blue-500 uppercase tracking-widest mt-0.5">Týdenní přehled</p>}
        </div>
        <button onClick={() => navigateDate('next')} className="p-3 text-slate-500 hover:text-white transition-colors">
          <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round"><path d="m9 18 6-6-6-6"/></svg>
        </button>
      </div>

      {/* Main Content Area */}
      <div className="bg-slate-800 rounded-[3rem] shadow-sm border border-slate-700 overflow-hidden flex flex-col h-[600px] md:h-[800px] relative">
        {viewMode === 'day' ? renderDayView() : renderWeekView()}
      </div>

      {/* Task Edit Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-slate-950/95 backdrop-blur-lg z-50 flex items-end sm:items-center justify-center p-4">
          <div className="bg-slate-900 w-full max-w-lg rounded-[32px] p-8 border border-slate-800 animate-slide-up max-h-[90vh] overflow-y-auto no-scrollbar shadow-2xl">
            <h3 className="text-2xl font-black text-white mb-6 uppercase tracking-tighter">{isEditing ? 'Upravit zakázku' : 'Nová zakázka'}</h3>
            <div className="space-y-6">
              <div className="space-y-1">
                <label className="text-xs font-black text-white uppercase px-1">Název akce</label>
                <input value={currentTask.title} onChange={e => setCurrentTask({...currentTask, title: e.target.value})} placeholder="např. Stěhování bytu 3+1" className="w-full bg-slate-800 rounded-xl p-4 text-white border-none font-bold" />
              </div>
              <div className="grid grid-cols-2 gap-4">
                 <div className="space-y-1">
                    <label className="text-xs font-black text-white uppercase px-1">Zákazník</label>
                    <input value={currentTask.customer} onChange={e => setCurrentTask({...currentTask, customer: e.target.value})} className="w-full bg-slate-800 rounded-xl p-3 text-sm text-white border-none" />
                 </div>
                 <div className="space-y-1">
                    <label className="text-xs font-black text-white uppercase px-1">Telefon</label>
                    <input value={currentTask.customerPhone} onChange={e => setCurrentTask({...currentTask, customerPhone: e.target.value})} className="w-full bg-slate-800 rounded-xl p-3 text-sm text-white border-none" />
                 </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                 <div className="space-y-1">
                    <label className="text-xs font-black text-white uppercase px-1">Začátek</label>
                    <input type="datetime-local" value={formatForInput(currentTask.start)} onChange={e => setCurrentTask({...currentTask, start: new Date(e.target.value)})} className="w-full bg-slate-800 rounded-xl p-3 text-xs text-white border-none" />
                 </div>
                 <div className="space-y-1">
                    <label className="text-xs font-black text-white uppercase px-1">Konec</label>
                    <input type="datetime-local" value={formatForInput(currentTask.end)} onChange={e => setCurrentTask({...currentTask, end: new Date(e.target.value)})} className="w-full bg-slate-800 rounded-xl p-3 text-xs text-white border-none" />
                 </div>
              </div>

              {/* Adresní pole bez sekce Logistika */}
              <div className="space-y-3">
                <div className="space-y-1">
                    <label className="text-xs font-black text-white uppercase px-1">Nakládka (Odkud)</label>
                    <div className="flex gap-2">
                        <input 
                            value={currentTask.from} 
                            onChange={e => setCurrentTask({...currentTask, from: e.target.value})} 
                            placeholder="Ulice, Město" 
                            className="flex-1 bg-slate-800 rounded-xl p-3 text-sm text-white border-none" 
                        />
                        <button 
                            onClick={() => openMap(currentTask.from)}
                            className="bg-slate-800 text-blue-400 p-3 rounded-xl hover:bg-slate-700 transition-colors border border-slate-700"
                            title="Otevřít v mapách"
                        >
                            <Icons.Map />
                        </button>
                    </div>
                </div>
                <div className="space-y-1">
                    <label className="text-xs font-black text-white uppercase px-1">Vykládka (Kam)</label>
                    <div className="flex gap-2">
                        <input 
                            value={currentTask.to} 
                            onChange={e => setCurrentTask({...currentTask, to: e.target.value})} 
                            placeholder="Ulice, Město" 
                            className="flex-1 bg-slate-800 rounded-xl p-3 text-sm text-white border-none" 
                        />
                        <button 
                            onClick={() => openMap(currentTask.to)}
                            className="bg-slate-800 text-blue-400 p-3 rounded-xl hover:bg-slate-700 transition-colors border border-slate-700"
                            title="Otevřít v mapách"
                        >
                            <Icons.Map />
                        </button>
                    </div>
                </div>
              </div>

              <div className="space-y-3">
                <label className="text-xs font-black text-white uppercase px-1">Tým (kliknutím vyber)</label>
                <div className="flex flex-wrap gap-2">
                   {workers.map(w => (
                     <button key={w.id} onClick={() => toggleResource(w.id, 'worker')} className={`px-4 py-2 rounded-xl text-xs font-black transition-all border ${currentTask.assignedWorkers?.includes(w.id) ? 'bg-blue-600 border-blue-500 text-white shadow-lg' : 'bg-slate-800 border-slate-700 text-white'}`}>{w.name}</button>
                   ))}
                </div>
              </div>

              <div className="space-y-3">
                <label className="text-xs font-black text-white uppercase px-1">Vozidla (kliknutím vyber)</label>
                <div className="flex flex-wrap gap-2">
                   {vehicles.map(v => (
                     <button 
                        key={v.id} 
                        onClick={() => toggleResource(v.id, 'vehicle')} 
                        className={`px-4 py-2 rounded-xl transition-all border flex flex-col items-center ${currentTask.assignedVehicles?.includes(v.id) ? 'bg-red-600 border-red-500 text-white shadow-lg' : 'bg-slate-800 border-slate-700 text-white'}`}
                    >
                        <span className="text-xs font-black">{v.model}</span>
                        <span className="text-[8px] opacity-60 font-bold uppercase tracking-wider">{v.plate}</span>
                    </button>
                   ))}
                </div>
              </div>

              {/* Sekce Poznámky s AI funkcí */}
              <div className="space-y-2 pt-2 border-t border-slate-800/50">
                <div className="flex items-center justify-between">
                    <label className="text-xs font-black text-white uppercase px-1">Poznámky</label>
                    <button 
                        onClick={parseNotesAndFill}
                        disabled={isAnalyzing}
                        className={`text-[9px] font-black uppercase tracking-widest px-3 py-1 rounded-full transition-colors flex items-center gap-1 ${isAnalyzing ? 'bg-slate-700 text-slate-400 cursor-not-allowed' : 'bg-blue-900/20 text-blue-400 hover:bg-blue-900/40'}`}
                    >
                        {isAnalyzing ? (
                          <>
                            <div className="w-2 h-2 border-2 border-slate-400 border-t-transparent rounded-full animate-spin"></div> Analyzuji...
                          </>
                        ) : (
                          <>
                            <Icons.Sparkles /> Rozpoznat údaje (AI)
                          </>
                        )}
                    </button>
                </div>
                <textarea 
                    value={currentTask.notes || ''} 
                    onChange={e => setCurrentTask({...currentTask, notes: e.target.value})} 
                    placeholder="Vložte text, např.: 'Karel Novák, 777123456, Nakládka: Praha 1, Vykládka: Brno'"
                    className="w-full bg-slate-800 rounded-xl p-4 text-sm text-white border-none min-h-[120px]"
                    rows={5}
                />
                <p className="text-[9px] text-slate-600 px-1">
                    Tip: Zkopírujte sem text emailu a klikněte na "Rozpoznat údaje" pro automatické vyplnění polí pomocí Gemini AI.
                </p>
              </div>

              <div className="flex gap-4 pt-4">
                <button onClick={() => setShowModal(false)} className="flex-1 text-slate-500 font-black uppercase text-xs tracking-widest">Zrušit</button>
                <button onClick={saveTask} className="flex-[2] bg-blue-600 text-white font-black py-4 rounded-2xl shadow-xl shadow-blue-600/20 uppercase text-xs tracking-widest">Uložit změny</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CalendarView;

import React, { useState, useEffect, useMemo } from 'react';
import { MoveTask, Worker, Vehicle } from '../types';
import { Icons } from '../constants';

interface DashboardProps {
  tasks: MoveTask[];
  workers: Worker[];
  vehicles: Vehicle[];
  user: {
    workerId?: string;
    role: 'admin' | 'user';
  };
}

const Dashboard: React.FC<DashboardProps> = ({ tasks, workers, vehicles, user }) => {
  const [selectedTask, setSelectedTask] = useState<MoveTask | null>(null);
  const [isDesktop, setIsDesktop] = useState(window.innerWidth >= 1024);

  useEffect(() => {
    const handleResize = () => setIsDesktop(window.innerWidth >= 1024);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const weeklyStats = useMemo(() => {
    const now = new Date();
    const startOfWeek = new Date(now);
    const day = now.getDay();
    const diff = now.getDate() - day + (day === 0 ? -6 : 1); // adjust when day is sunday
    startOfWeek.setDate(diff);
    startOfWeek.setHours(0, 0, 0, 0);

    const endOfWeek = new Date(startOfWeek);
    endOfWeek.setDate(startOfWeek.getDate() + 6);
    endOfWeek.setHours(23, 59, 59, 999);

    const weekTasks = tasks.filter(t => t.start >= startOfWeek && t.start <= endOfWeek);
    const completed = weekTasks.filter(t => t.status === 'Completed').length;
    return { total: weekTasks.length, completed };
  }, [tasks]);

  const monthlyStats = useMemo(() => {
    const now = new Date();
    const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
    const endOfMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0);
    endOfMonth.setHours(23, 59, 59, 999);

    const monthTasks = tasks.filter(t => t.start >= startOfMonth && t.start <= endOfMonth);
    const completed = monthTasks.filter(t => t.status === 'Completed').length;
    return { total: monthTasks.length, completed };
  }, [tasks]);

  const isToday = (date: Date) => {
    const today = new Date();
    return date.getDate() === today.getDate() &&
      date.getMonth() === today.getMonth() &&
      date.getFullYear() === today.getFullYear();
  };

  const isTomorrow = (date: Date) => {
    const tomorrow = new Date();
    tomorrow.setDate(tomorrow.getDate() + 1);
    return date.getDate() === tomorrow.getDate() &&
      date.getMonth() === tomorrow.getMonth() &&
      date.getFullYear() === tomorrow.getFullYear();
  };

  // Logic for "My assigned tasks" specifically for the top start cards
  const myAssignedTasks = user.workerId 
    ? tasks.filter(t => t.assignedWorkers.includes(user.workerId!))
    : [];

  const myTodayStartTask = [...myAssignedTasks]
    .filter(t => isToday(t.start))
    .sort((a, b) => a.start.getTime() - b.start.getTime())[0];

  const myTomorrowStartTask = [...myAssignedTasks]
    .filter(t => isTomorrow(t.start))
    .sort((a, b) => a.start.getTime() - b.start.getTime())[0];

  // Logic for lists (Admins see all, users see assigned)
  const myTasksForList = user.role === 'admin' 
    ? tasks 
    : tasks.filter(t => t.assignedWorkers.includes(user.workerId || ''));

  const todayTasks = myTasksForList.filter(t => isToday(t.start));
  const tomorrowTasks = myTasksForList.filter(t => isTomorrow(t.start));

  // Find the company's first task for tomorrow (for the notification section)
  const firstTaskTomorrowGlobal = [...tasks]
    .filter(t => isTomorrow(t.start))
    .sort((a, b) => a.start.getTime() - b.start.getTime())[0];

  const handleOpenMaps = (address?: string) => {
    if (!address) return;
    const url = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(address)}`;
    window.open(url, '_blank');
  };

  const sendNotification = (type: 'whatsapp' | 'sms', task: MoveTask) => {
    const timeStr = `${task.start.getHours()}:${task.start.getMinutes().toString().padStart(2, '0')}`;
    const message = `Stěhovák 2.0: Připomínka zítřejšího startu. První zakázka '${task.title}' začíná v ${timeStr}. Buďte připraveni!`;
    const encodedMsg = encodeURIComponent(message);

    if (type === 'whatsapp') {
      window.open(`https://wa.me/?text=${encodedMsg}`, '_blank');
    } else {
      window.location.href = `sms:?body=${encodedMsg}`;
    }
  };

  const formatTime = (date: Date) => {
    return `${date.getHours()}:${date.getMinutes().toString().padStart(2, '0')}`;
  };

  interface TaskCardProps {
    task: MoveTask;
    index?: number;
  }

  const TaskCard: React.FC<TaskCardProps> = ({ task, index = 0 }) => (
    <button
      onClick={() => setSelectedTask(task)}
      className="w-full bg-slate-800 p-5 md:p-8 rounded-[2.5rem] shadow-sm border border-slate-700 flex items-center gap-5 md:gap-8 hover:bg-slate-700 hover:border-blue-500/30 transition-all cursor-pointer active:scale-[0.98] group animate-slide-up text-left relative overflow-hidden"
      style={{ 
          animationDelay: `${index * 150}ms`,
          animationFillMode: 'both' 
      }}
    >
      <div className="flex flex-col items-center justify-center bg-slate-900 group-hover:bg-blue-600 group-hover:text-white rounded-[2rem] p-4 md:p-6 min-w-[75px] md:min-w-[100px] transition-colors duration-300 text-slate-400">
        <span className="font-black text-xl md:text-3xl leading-none group-hover:text-white transition-colors">
          {task.start.getHours()}
        </span>
        <span className="text-[10px] md:text-xs font-black opacity-40 uppercase mt-1">HOD</span>
      </div>

      <div className="flex-1 min-w-0">
        <h3 className="font-black text-slate-100 text-base md:text-2xl leading-tight group-hover:text-blue-400 transition-colors">{task.title}</h3>
        <p className="text-xs md:text-sm text-slate-400 font-bold mt-1 uppercase tracking-tight">{task.customer}</p>
        <div className="flex items-center gap-2 mt-2 md:mt-3">
          <div className="flex -space-x-2">
            {task.assignedWorkers.slice(0, 3).map((_, i) => (
              <div key={i} className="w-5 h-5 md:w-8 md:h-8 rounded-full bg-slate-700 border-2 border-slate-800 flex items-center justify-center text-[8px] md:text-[10px] font-black text-blue-400"><Icons.User /></div>
            ))}
          </div>
          <span className="text-[10px] md:text-sm text-slate-500 font-bold truncate">
            {task.from}
          </span>
        </div>
      </div>

      <div className="flex flex-col items-end gap-2">
        <div className={`w-3 h-3 md:w-5 md:h-5 rounded-full shadow-[0_0_10px_rgba(0,0,0,0.5)] ${
            task.status === 'Confirmed' ? 'bg-blue-500' : 
            task.status === 'In Progress' ? 'bg-red-500 animate-pulse' : 'bg-slate-600'
        }`} />
        <div className="text-slate-600 group-hover:text-blue-400 transition-colors">
            <Icons.ChevronRight />
        </div>
      </div>
    </button>
  );

  return (
    <div className="space-y-10">
      {/* Personalized Start Times */}
      <div className="grid grid-cols-2 gap-4 md:gap-8">
        <StartCard 
          label="Tvůj dnešní start" 
          time={myTodayStartTask ? formatTime(myTodayStartTask.start) : '--:--'} 
          subtitle={myTodayStartTask?.title || 'Dnes nemáš zakázku'}
          color="red" 
        />
        <StartCard 
          label="Tvůj zítřejší start" 
          time={myTomorrowStartTask ? formatTime(myTomorrowStartTask.start) : '--:--'} 
          subtitle={myTomorrowStartTask?.title || 'Zítra nemáš zakázku'}
          color="blue" 
        />
      </div>

      {/* Desktop Statistics Section */}
      {isDesktop && (
        <section className="grid grid-cols-2 gap-4 md:gap-8 animate-fade-in">
          <StatCard 
            title="Tento týden"
            completed={weeklyStats.completed}
            total={weeklyStats.total}
            color="blue"
          />
          <StatCard 
            title="Tento měsíc"
            completed={monthlyStats.completed}
            total={monthlyStats.total}
            color="red"
          />
        </section>
      )}

      {/* Tomorrow Morning Reminder Section (Admin/Global focus) */}
      {user.role === 'admin' && firstTaskTomorrowGlobal && (
        <section className="bg-blue-600/10 border border-blue-500/20 rounded-[3rem] p-6 md:p-10 animate-fade-in relative overflow-hidden">
          <div className="absolute top-0 right-0 p-8 opacity-10 pointer-events-none transform scale-150">
            <Icons.Sparkles />
          </div>
          <div className="relative z-10">
            <div className="flex items-center gap-2 mb-4 md:mb-6">
               <span className="w-2 h-2 md:w-3 md:h-3 bg-blue-400 rounded-full animate-pulse shadow-[0_0_8px_#60a5fa]" />
               <h2 className="text-[10px] md:text-sm font-black text-blue-400 uppercase tracking-widest">Zítřejší ranní start (Firma)</h2>
            </div>
            <div className="flex items-end justify-between">
               <div>
