import { GoogleGenAI, Modality, Type } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

// Striktní systémová instrukce pro vynucení češtiny
const SYSTEM_INSTRUCTION = "Jsi expertní logistický asistent pro českou aplikaci 'Stěhovák 2.0'. TVŮJ JAZYK JE ČEŠTINA. \n\n1. Veškerá komunikace musí probíhat výhradně v češtině (Czech language only).\n2. Odpovídej věcně, profesionálně a s ohledem na české reálie.\n3. Používej metrický systém (metry, kilogramy) a českou měnu (Kč).\n4. Data formátuj jako DD.MM.RRRR.\n5. Pokud uživatel zadá dotaz v jiném jazyce, přelož si ho a odpověz česky.";

export const geminiService = {
  /**
   * Fast responses (Gemini 2.5 Flash Lite)
   */
  async chatFast(prompt: string): Promise<string> {
    const ai = getAI();
    const response = await ai.models.generateContent({
      model: 'gemini-flash-lite-latest',
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
      },
    });
    return response.text || "Bez odpovědi.";
  },

  /**
   * Extract Structured Data from Notes (Gemini 3 Flash Preview)
   * Vylepšeno pro vyšší přesnost rozpoznání adres a kontaktů.
   */
  async extractTaskFromNotes(noteText: string): Promise<{
    title?: string;
    customer?: string;
    customerPhone?: string;
    from?: string;
    to?: string;
  }> {
    const ai = getAI();

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Analyzuj následující text poznámky k logistické/stěhovací zakázce a extrahuj strukturovaná data.

      VSTUPNÍ TEXT POZNÁMKY:
      "${noteText}"

      INSTRUKCE PRO EXTRAKCI:
      1. **customer**: Najdi jméno zákazníka. Hledej fráze jako "Klient:", "Pan/Paní" nebo jména na začátku textu.
      2. **customerPhone**: Najdi telefonní číslo. Pokud je to české číslo, zformátuj ho s mezerami (např. +420 777 888 999).
      3. **from**: Adresa NAKLÁDKY (start). Hledej klíčová slova: "z:", "odkud:", "nakládka:", "adresa 1", "byt A".
      4. **to**: Adresa VYKLÁDKY (cíl). Hledej klíčová slova: "do:", "kam:", "vykládka:", "adresa 2", "byt B".
      5. **title**: Vytvoř stručný název zakázky. 
         - Pokud jsou známa města, použij formát: "Stěhování: [Město Odkud] -> [Město Kam]".
         - Jinak použij předmět stěhování, např. "Převoz gauče", "Stěhování 2+kk".

      Pokud některý údaj v textu chybí, vrať pro daný klíč prázdný řetězec.`,
      config: {
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            customer: { type: Type.STRING },
            customerPhone: { type: Type.STRING },
            from: { type: Type.STRING },
            to: { type: Type.STRING }
          }
        }
      },
    });

    try {
      return JSON.parse(response.text || "{}");
    } catch (e) {
      console.error("Failed to parse JSON from AI", e);
      return {};
    }
  },

  /**
   * Transcribe Audio (Gemini 3 Flash Preview)
   */
  async transcribeAudio(base64Audio: string, mimeType: string): Promise<string> {
    const ai = getAI();
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { data: base64Audio, mimeType: mimeType } },
          { text: "Přepiš tuto zvukovou nahrávku do textu. Pouze čistý text, žádné úvodní fráze." }
        ]
      },
    });
    return response.text || "";
  },

  /**
   * Generate Speech / TTS (Gemini 2.5 Flash Preview TTS)
   */
  async generateSpeech(text: string): Promise<string | null> {
    const ai = getAI();
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: 'Kore' }, // Kore, Puck, Charon, Fenrir, Zephyr
            },
        },
      },
    });

    // API returns raw PCM data in inlineData.data
    return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data || null;
  },

  /**
   * Thinking mode for complex queries (Gemini 3 Pro)
   */
  async thinkComplex(prompt: string): Promise<string> {
    const ai = getAI();
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        thinkingConfig: { thinkingBudget: 32768 }
      },
    });
    return response.text || "Nebyla vygenerována žádná odpověď.";
  },

  /**
   * Analyze images (Gemini 3 Pro)
   */
  async analyzeImage(imagePrompt: string, base64Image: string, mimeType: string): Promise<string> {
    const ai = getAI();
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: {
        parts: [
          { inlineData: { data: base64Image, mimeType: mimeType } },
          { text: imagePrompt }
        ]
      },
      config: {
        systemInstruction: SYSTEM_INSTRUCTION
      }
    });
    return response.text || "Nepodařilo se analyzovat obrázek.";
  },

  /**
   * Generate images (Gemini 3 Pro Image)
   */
  async generateImage(prompt: string, size: '1K' | '2K' | '4K', aspectRatio: string): Promise<string | null> {
    const ai = getAI();
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: { parts: [{ text: `Vysoce kvalitní, fotorealistický obrázek, české prostředí: ${prompt}` }] },
      config: {
        imageConfig: {
          aspectRatio: aspectRatio,
          imageSize: size
        }
      }
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
    return null;
  },

  /**
   * Edit images with text prompts (Gemini 2.5 Flash Image)
   */
  async editImage(prompt: string, base64Image: string, mimeType: string): Promise<string | null> {
    const ai = getAI();
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          { inlineData: { data: base64Image, mimeType: mimeType } },
          { text: prompt }
        ]
      },
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
    return null;
  },

  /**
   * Maps Grounding (Gemini 2.5 Flash)
   */
  async getMapsInfo(query: string, lat?: number, lng?: number): Promise<{ text: string, links: any[] }> {
    const ai = getAI();
    const config: any = {
      tools: [{ googleMaps: {} }],
      systemInstruction: SYSTEM_INSTRUCTION
    };

    if (lat !== undefined && lng !== undefined) {
      config.toolConfig = {
        retrievalConfig: {
          latLng: { latitude: lat, longitude: lng }
        }
      };
    }

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: `Najdi v okolí (odpověz česky): ${query}`,
      config
    });

    return {
      text: response.text || "",
      links: response.candidates?.[0]?.groundingMetadata?.groundingChunks || []
    };
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import { MoveTask, Worker, Vehicle } from '../types';
import { Icons } from '../constants';

interface DashboardProps {
  tasks: MoveTask[];
  workers: Worker[];
  vehicles: Vehicle[];
  user: {
    workerId?: string;
    role: 'admin' | 'user';
  };
}

const Dashboard: React.FC<DashboardProps> = ({ tasks, workers, vehicles, user }) => {
  const [selectedTask, setSelectedTask] = useState<MoveTask | null>(null);
  const [isDesktop, setIsDesktop] = useState(window.innerWidth >= 1024);

  useEffect(() => {
    const handleResize = () => setIsDesktop(window.innerWidth >= 1024);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const weeklyStats = useMemo(() => {
    const now = new Date();
    const startOfWeek = new Date(now);
    const day = now.getDay();
    const diff = now.getDate() - day + (day === 0 ? -6 : 1); // adjust when day is sunday
    startOfWeek.setDate(diff);
    startOfWeek.setHours(0, 0, 0, 0);

    const endOfWeek = new Date(startOfWeek);
    endOfWeek.setDate(startOfWeek.getDate() + 6);
    endOfWeek.setHours(23, 59, 59, 999);

    const weekTasks = tasks.filter(t => t.start >= startOfWeek && t.start <= endOfWeek);
    const completed = weekTasks.filter(t => t.status === 'Completed').length;
    return { total: weekTasks.length, completed };
  }, [tasks]);

  const monthlyStats = useMemo(() => {
    const now = new Date();
    const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
    const endOfMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0);
    endOfMonth.setHours(23, 59, 59, 999);

    const monthTasks = tasks.filter(t => t.start >= startOfMonth && t.start <= endOfMonth);
    const completed = monthTasks.filter(t => t.status === 'Completed').length;
    return { total: monthTasks.length, completed };
  }, [tasks]);

  const isToday = (date: Date) => {
    const today = new Date();
    return date.getDate() === today.getDate() &&
      date.getMonth() === today.getMonth() &&
      date.getFullYear() === today.getFullYear();
  };

  const isTomorrow = (date: Date) => {
    const tomorrow = new Date();
    tomorrow.setDate(tomorrow.getDate() + 1);
    return date.getDate() === tomorrow.getDate() &&
      date.getMonth() === tomorrow.getMonth() &&
      date.getFullYear() === tomorrow.getFullYear();
  };

  // Logic for "My assigned tasks" specifically for the top start cards
  const myAssignedTasks = user.workerId 
    ? tasks.filter(t => t.assignedWorkers.includes(user.workerId!))
    : [];

  const myTodayStartTask = [...myAssignedTasks]
    .filter(t => isToday(t.start))
    .sort((a, b) => a.start.getTime() - b.start.getTime())[0];

  const myTomorrowStartTask = [...myAssignedTasks]
    .filter(t => isTomorrow(t.start))
    .sort((a, b) => a.start.getTime() - b.start.getTime())[0];

  // Logic for lists (Admins see all, users see assigned)
  const myTasksForList = user.role === 'admin' 
    ? tasks 
    : tasks.filter(t => t.assignedWorkers.includes(user.workerId || ''));

  const todayTasks = myTasksForList.filter(t => isToday(t.start));
  const tomorrowTasks = myTasksForList.filter(t => isTomorrow(t.start));

  // Find the company's first task for tomorrow (for the notification section)
  const firstTaskTomorrowGlobal = [...tasks]
    .filter(t => isTomorrow(t.start))
    .sort((a, b) => a.start.getTime() - b.start.getTime())[0];

  const handleOpenMaps = (address?: string) => {
    if (!address) return;
    const url = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(address)}`;
    window.open(url, '_blank');
  };

  const sendNotification = (type: 'whatsapp' | 'sms', task: MoveTask) => {
    const timeStr = `${task.start.getHours()}:${task.start.getMinutes().toString().padStart(2, '0')}`;
    const dateStr = task.start.toLocaleDateString('cs-CZ');

    // Získání telefonních čísel všech přiřazených pracovníků
    const assignedTeam = workers.filter(w => task.assignedWorkers.includes(w.id));
    const recipients = assignedTeam
        .map(w => w.phone.replace(/\s+/g, '')) // Odstranit mezery
        .filter(p => p.length > 0)
        .join(','); // Čárka je standardní oddělovač pro hromadné SMS

    // Detailní zpráva o zakázce
    const message = `🚚 Stěhovák 2.0 INFO\n` +
                    `Zítřejší akce: ${task.title}\n` +
                    `⏰ Start: ${timeStr} (${dateStr})\n` +
                    `📍 ${task.from} -> ${task.to}\n` +
                    `📞 Klient: ${task.customer} (${task.customerPhone || 'bez tel.'})`;

    const encodedMsg = encodeURIComponent(message);

    if (type === 'whatsapp') {
      // WhatsApp neumí přímo hromadné zprávy přes URL schéma bez broadcast listu,
      // otevřeme tedy sdílení textu (uživatel vybere příjemce).
      window.open(`https://wa.me/?text=${encodedMsg}`, '_blank');
    } else {
      // Otevře nativní SMS aplikaci s předvyplněnými příjemci a textem
      window.open(`sms:${recipients}?body=${encodedMsg}`, '_self');
    }
  };

  const formatTime = (date: Date) => {
    return `${date.getHours()}:${date.getMinutes().toString().padStart(2, '0')}`;
  };

  interface TaskCardProps {
    task: MoveTask;
    index?: number;
  }

  const TaskCard: React.FC<TaskCardProps> = ({ task, index = 0 }) => (
    <button
      onClick={() => setSelectedTask(task)}
      className="w-full bg-slate-800 p-5 md:p-8 rounded-[2.5rem] shadow-sm border border-slate-700 flex items-center gap-5 md:gap-8 hover:bg-slate-700 hover:border-blue-500/30 transition-all cursor-pointer active:scale-[0.98] group animate-slide-up text-left relative overflow-hidden"
      style={{ 
          animationDelay: `${index * 150}ms`,
          animationFillMode: 'both' 
      }}
    >
      <div className="flex flex-col items-center justify-center bg-slate-900 group-hover:bg-blue-600 group-hover:text-white rounded-[2rem] p-4 md:p-6 min-w-[75px] md:min-w-[100px] transition-colors duration-300 text-slate-400">
        <span className="font-black text-xl md:text-3xl leading-none group-hover:text-white transition-colors">
          {task.start.getHours()}
        </span>
        <span className="text-[10px] md:text-xs font-black opacity-40 uppercase mt-1">HOD</span>
      </div>

      <div className="flex-1 min-w-0">
        <h3 className="font-black text-slate-100 text-base md:text-2xl leading-tight group-hover:text-blue-400 transition-colors">{task.title}</h3>
        <p className="text-xs md:text-sm text-slate-400 font-bold mt-1 uppercase tracking-tight">{task.customer}</p>
        <div className="flex items-center gap-2 mt-2 md:mt-3">
          <div className="flex -space-x-2">
            {task.assignedWorkers.slice(0, 3).map((_, i) => (
              <div key={i} className="w-5 h-5 md:w-8 md:h-8 rounded-full bg-slate-700 border-2 border-slate-800 flex items-center justify-center text-[8px] md:text-[10px] font-black text-blue-400"><Icons.User /></div>
            ))}
          </div>
          <span className="text-[10px] md:text-sm text-slate-500 font-bold truncate">
            {task.from}
          </span>
        </div>
      </div>

      <div className="flex flex-col items-end gap-2">
        <div className={`w-3 h-3 md:w-5 md:h-5 rounded-full shadow-[0_0_10px_rgba(0,0,0,0.5)] ${
            task.status === 'Confirmed' ? 'bg-blue-500' : 
            task.status === 'In Progress' ? 'bg-red-500 animate-pulse' : 'bg-slate-600'
        }`} />
        <div className="text-slate-600 group-hover:text-blue-400 transition-colors">
            <Icons.ChevronRight />
        </div>
      </div>
    </button>
  );

  return (
    <div className="space-y-10">
      {/* Personalized Start Times */}
      <div className="grid grid-cols-2 gap-4 md:gap-8">
        <StartCard 
          label="Tvůj dnešní start" 
          time={myTodayStartTask ? formatTime(myTodayStartTask.start) : '--:--'} 
          subtitle={myTodayStartTask?.title || 'Dnes nemáš zakázku'}
          color="red" 
        />
        <StartCard 
          label="Tvůj zítřejší start" 
          time={myTomorrowStartTask ? formatTime(myTomorrowStartTask.start) : '--:--'} 
          subtitle={myTomorrowStartTask?.title || 'Zítra nemáš zakázku'}
          color="blue" 
        />
      </div>

      {/* Desktop Statistics Section */}
      {isDesktop && (
        <section className="grid grid-cols-2 gap-4 md:gap-8 animate-fade-in">
          <StatCard 
            title="Tento týden"
            completed={weeklyStats.completed}
            total={weeklyStats.total}
            color="blue"
          />
          <StatCard 
            title="Tento měsíc"
            completed={monthlyStats.completed}
            total={monthlyStats.total}
            color="red"
          />
        </section>
      )}

      {/* Tomorrow Morning Reminder Section (Admin/Global focus) */}
      {user.role === 'admin' && firstTaskTomorrowGlobal && (
        <section className="bg-blue-600/10 border border-blue-500/20 rounded-[3rem] p-6 md:p-10 animate-fade-in relative overflow-hidden">
          <div className="absolute top-0 right-0 p-8 opacity-10 pointer-events-none transform scale-150">
            <Icons.Sparkles />
          </div>
          <div className="relative z-10">
            <div className="flex items-center gap-2 mb-4 md:mb-6">
               <span className="w-2 h-2 md:w-3 md:h-3 bg-blue-400 rounded-full animate-pulse shadow-[0_0_8px_#60a5fa]" />
               <h2 className="text-[10px] md:text-sm font-black text-blue-400 uppercase tracking-widest">Zítřejší ranní start (Firma)</h2>
            </div>
            <div className="flex items-end justify-between">
               <div>
                  <p className="text-2xl md:text-5xl font-black text-white tracking-tighter">{formatTime(firstTaskTomorrowGlobal.start)}</p>
                  <p className="text-xs md:text-lg font-bold text-slate-400 uppercase truncate max-w-[180px] md:max-w-md mt-1">{firstTaskTomorrowGlobal.title}</p>
               </div>
               <div className="flex gap-2 md:gap-4">
                  <button 
                    onClick={() => sendNotification('sms', firstTaskTomorrowGlobal)}
                    className="p-4 md:p-6 bg-slate-800 text-white rounded-2xl border border-slate-700 hover:bg-slate-700 transition-all shadow-lg active:scale-90"
                  >
                    <div className="md:scale-125"><Icons.Message /></div>
                  </button>
                  <button 
                    onClick={() => sendNotification('whatsapp', firstTaskTomorrowGlobal)}
                    className="p-4 md:p-6 bg-green-600 text-white rounded-2xl border border-green-500 hover:bg-green-500 transition-all shadow-lg shadow-green-600/20 active:scale-90"
                  >
                    <div className="md:scale-125"><Icons.WhatsApp /></div>
                  </button>
               </div>
            </div>
          </div>
        </section>
      )}

      {/* Main Task Lists Container - Responsive Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 md:gap-12">
        <section className="space-y-5 md:space-y-8">
            <div className="flex items-center justify-between px-2">
            <h2 className="text-xl md:text-3xl font-black text-slate-100 tracking-tighter uppercase">Dnešní <span className="text-red-500">Mise</span></h2>
            <div className="w-2 h-2 md:w-3 md:h-3 rounded-full bg-red-500 animate-pulse shadow-[0_0_8px_#ef4444]" />
            </div>
            <div className="space-y-4 md:space-y-6">
            {todayTasks.length > 0 ? todayTasks.map((task, index) => (
                <TaskCard key={task.id} task={task} index={index} />
            )) : (
                <div className="bg-slate-800/50 rounded-[2.5rem] p-10 text-center border-2 border-dashed border-slate-700 animate-fade-in">
                <p className="text-xs md:text-sm font-black text-slate-600 uppercase tracking-widest">Žádné dnešní úkoly</p>
                </div>
            )}
            </div>
        </section>

        <section className="space-y-5 md:space-y-8">
            <h2 className="text-xl md:text-3xl font-black text-slate-100 tracking-tighter px-2 uppercase">Plány <span className="text-blue-500">Zítra</span></h2>
            <div className="space-y-4 md:space-y-6">
            {tomorrowTasks.length > 0 ? tomorrowTasks.map((task, index) => (
                <TaskCard key={task.id} task={task} index={index} />
            )) : (
                <div className="bg-slate-800/50 rounded-[2.5rem] p-10 text-center border-2 border-dashed border-slate-700 animate-fade-in">
                <p className="text-xs md:text-sm font-black text-slate-600 uppercase tracking-widest">Zítra volno</p>
                </div>
            )}
            </div>
        </section>
      </div>

      {/* Task Detail Modal */}
      {selectedTask && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md z-50 flex items-end sm:items-center justify-center p-4" onClick={() => setSelectedTask(null)}>
          <div 
            className="bg-slate-900 w-full max-w-md rounded-[3rem] p-8 shadow-2xl animate-slide-up border border-slate-800"
            onClick={e => e.stopPropagation()}
          >
            <div className="flex justify-between items-start mb-8">
              <div>
                <span className={`text-[10px] font-black uppercase tracking-[0.2em] px-3 py-1 text-white rounded-lg mb-3 inline-block ${selectedTask.status === 'Confirmed' ? 'bg-red-600' : 'bg-blue-600'}`}>
                  {selectedTask.status}
                </span>
                <h3 className="text-3xl font-black text-white tracking-tighter">{selectedTask.title}</h3>
              </div>
              <button onClick={() => setSelectedTask(null)} className="bg-slate-800 p-3 rounded-2xl hover:bg-slate-700 transition-colors text-slate-400">
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
              </button>
            </div>

            <div className="space-y-8">
              <div className="flex items-center justify-between bg-blue-600 text-white p-6 rounded-[2rem] shadow-xl shadow-blue-600/20">
                <div className="flex-1">
                  <p className="text-[10px] font-black text-white/50 uppercase tracking-widest mb-1">Zákazník</p>
                  <p className="text-xl font-black leading-tight">{selectedTask.customer}</p>
                </div>
                {selectedTask.customerPhone && (
                  <a href={`tel:${selectedTask.customerPhone.replace(/\s+/g, '')}`} className="bg-slate-900/40 text-white p-4 rounded-2xl shadow-lg active:scale-95 transition-all">
                    <Icons.Phone />
                  </a>
                )}
              </div>

              <div className="grid grid-cols-2 gap-4">
                <button onClick={() => handleOpenMaps(selectedTask.from)} className="bg-slate-800 p-6 rounded-[2rem] text-left hover:bg-slate-700 transition-all border border-slate-700">
                  <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-2">PŘEVZETÍ</p>
                  <p className="text-xs font-black text-slate-200 truncate">{selectedTask.from}</p>
                </button>
                <button onClick={() => handleOpenMaps(selectedTask.to)} className="bg-slate-800 p-6 rounded-[2rem] text-left hover:bg-slate-700 transition-all border border-slate-700">
                  <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-2">CÍL</p>
                  <p className="text-xs font-black text-slate-200 truncate">{selectedTask.to}</p>
                </button>
              </div>

              <button 
                onClick={() => setSelectedTask(null)}
                className="w-full bg-blue-600 text-white font-black py-5 rounded-[2rem] shadow-xl shadow-blue-600/20 transition-all active:scale-95 text-sm uppercase tracking-widest hover:bg-blue-500"
              >
                Potvrdit hotovo
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const StatCard = ({ title, completed, total, color }: { title: string, completed: number, total: number, color: 'blue' | 'red' }) => {
    const percentage = total > 0 ? (completed / total) * 100 : 0;
    const themes = {
        blue: {
            border: 'border-blue-500/30',
            text: 'text-blue-400',
            progressBg: 'bg-blue-900/50',
            progressFill: 'bg-blue-500',
        },
        red: {
            border: 'border-red-500/30',
            text: 'text-red-500',
            progressBg: 'bg-red-900/50',
            progressFill: 'bg-red-500',
        },
    };
    const theme = themes[color];

    return (
        <div className={`p-6 md:p-8 rounded-[2.5rem] bg-slate-800 border ${theme.border} shadow-xl`}>
            <p className={`text-[10px] md:text-sm font-black uppercase tracking-widest mb-4 ${theme.text}`}>{title}</p>
            <div className="flex items-end justify-between">
                <div>
                    <span className="text-4xl md:text-5xl font-black text-white tracking-tighter">{completed}</span>
                    <span className="text-xl md:text-2xl font-bold text-slate-600 tracking-tighter"> / {total}</span>
                </div>
                <span className="text-sm md:text-base font-bold text-slate-400">Hotovo</span>
            </div>
            <div className={`w-full h-2 md:h-3 ${theme.progressBg} rounded-full mt-4 overflow-hidden`}>
                <div className={`h-full ${theme.progressFill} rounded-full transition-all duration-500`} style={{ width: `${percentage}%` }}></div>
            </div>
        </div>
    );
};

const StartCard = ({ label, time, subtitle, color }: { label: string, time: string, subtitle: string, color: 'blue' | 'red' }) => {
  const themes = {
    blue: 'border-blue-500/30 text-blue-400',
    red: 'border-red-500/30 text-red-500'
  };

  return (
    <div className={`p-6 md:p-10 rounded-[2.5rem] bg-slate-800 border ${themes[color]} flex flex-col items-center text-center shadow-xl transition-transform hover:-translate-y-1 animate-fade-in`}>
      <p className="text-[9px] md:text-xs font-black uppercase tracking-widest opacity-60 mb-2">{label}</p>
      <span className="text-4xl md:text-6xl font-black text-white tracking-tighter mb-1 md:mb-3">{time}</span>
      <p className="text-[9px] md:text-sm font-bold text-slate-500 uppercase truncate w-full px-2">{subtitle}</p>
    </div>
  );
};

export default Dashboard;
